NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Mark'

CHAPTERS = {
    1: {
        1: 'Jeesuksen Kristuksen, Jumalan Pojan, evankeliumin alku.',
        2: 'Kuten Profeetoissa on kirjoitettuna: "Katso, minä lähetän enkelini edelläsi, ja hän on valmistava tiesi sinun eteesi."',
        3: '"Airuen ääni kuuluu erämaassa: \'Valmistakaa Herralle tie, tehkää hänen polkunsa suoriksi\'".',
        4: 'Tapahtui, että Johannes kastoi erämaassa ja saarnasi mielenmuutoksen kastetta syntien anteeksiantamiseksi.',
        5: 'Koko Juudean maa ja kaikki jerusalemilaiset vaelsivat hänen luokseen, ja hän kastoi heitä Jordanin virrassa, kun he tunnustivat syntinsä.',
        6: 'Mutta Johanneksella oli puku kamelinkarvoista ja vyötäisillään nahkavyö, ja hän söi heinäsirkkoja ja metsähunajaa.',
        7: 'Hän saarnasi sanoen: "Minun jälkeeni tulee minua voimakkaampi, jonka sandaalien nyörejä en ole kelvollinen kumartuneena avaamaan.',
        8: 'Minä kastan teidät vedellä, mutta hän kastaa teidät Pyhällä Hengellä."',
        9: 'Tapahtui, että niinä päivinä Jeesus tuli Galilean Nasaretista, ja Johannes kastoi hänet Jordanissa.',
        10: 'Heti, vedestä noustessaan hän näki taivaitten aukeavan ja Hengen laskeutuvan kyyhkysenä päälleen.',
        11: 'Taivaista tuli ääni: "Sinä olet minun rakas Poikani, sinuun olen mieltynyt."',
        12: 'Heti sen jälkeen Henki ajoi hänet erämaahan.',
        13: 'Hän oli siellä erämaassa neljäkymmentä päivää saatanan kiusattavana, hän oli petojen seassa, ja enkelit palvelivat häntä.',
        14: 'Mutta kun Johannes oli pantu vankeuteen, Jeesus meni Galileaan ja saarnasi Jumalan valtakunnan evankeliumia',
        15: 'ja sanoi: "Aika on täyttynyt, ja Jumalan valtakunta on tullut lähelle. Muuttakaa mielenne ja uskokaa evankeliumi."',
        16: 'Mutta kulkiessaan Galilean järven rantaa hän näki Simonin ja Andreaan, Simonin veljen, heittävän verkkoa järveen, sillä he olivat kalastajia.',
        17: 'Jeesus sanoi heille: "Seuratkaa minua, niin teen teistä ihmisten kalastajia."',
        18: 'Heti he jättivät verkkonsa ja seurasivat häntä.',
        19: 'Kuljettuaan siitä vähän eteenpäin hän näki Jaakobin, Sebedeuksen pojan, ja Johanneksen, hänen veljensä, heidätkin veneessä, kunnostamassa verkkojaan.',
        20: 'Heti hän kutsui heidät, ja he jättivät isänsä, Sebedeuksen, palkkalaisineen veneeseen ja lähtivät seuraamaan häntä.',
        21: 'He saapuivat Kapernaumiin, ja hän meni heti sapattina synagogaan ja opetti.',
        22: 'He olivat hämmästyksissään hänen opetuksestaan, sillä hän opetti heitä niin kuin se, jolla on valta, eikä niin kuin kirjanoppineet.',
        23: 'Heidän synagogassaan oli mies, jossa oli saastainen henki, ja se huusi',
        24: 'sanoen: "Mitä sinulla on meidän kanssamme tekemistä, Jeesus Nasaretilainen? Oletko tullut meitä tuhoamaan? Tunnen sinut, kuka olet, sinä Jumalan Pyhä."',
        25: 'Jeesus nuhteli sitä sanoen: "Vaikene ja lähde hänestä."',
        26: 'Saastainen henki kouristi häntä ja lähti hänestä huutaen suurella äänellä.',
        27: 'He hämmästyivät kaikki, niin että kyselivät toisiltaan sanoen: "Mitä tämä on? Uusi, voimallinen oppi! Hän käskee saastaisia henkiäkin, ja ne tottelevat häntä."',
        28: 'Hänen maineensa levisi heti koko ympäristöön, kaikkialle Galileaan.',
        29: 'Tultuaan ulos synagogasta he menivät heti Simonin ja Andreaan taloon Jaakobin ja Johanneksen kanssa.',
        30: 'Simonin anoppi makasi sairaana kuumeessa, ja heti he puhuivat hänestä Jeesukselle.',
        31: 'Hän meni hänen luokseen ja nosti hänet ylös tarttuen hänen käteensä, ja kuume lähti hänestä, ja hän palveli heitä.',
        32: 'Mutta illan tultua, kun aurinko oli laskenut, tuotiin hänen luokseen kaikki sairaat ja riivatut,',
        33: 'ja koko kaupunki oli kokoontunut oven eteen.',
        34: 'Hän paransi monta, jotka sairastivat monenlaisia tauteja, ja paljon riivaajia hän ajoi ulos eikä sallinut riivaajien puhua, koska ne tunsivat hänet.',
        35: 'Varhain aamulla, kun vielä oli pimeä, hän nousi, lähti ulos ja meni autioon paikkaan, ja siellä hän rukoili.',
        36: 'Mutta Simon ja ne, jotka olivat hänen kanssaan, riensivät hänen jälkeensä,',
        37: 'ja löydettyään hänet he sanoivat hänelle: "Kaikki etsivät sinua."',
        38: 'Hän sanoi heille: "Menkäämme muualle, läheisiin kyliin, jotta sielläkin saarnaisin, sillä sitä varten olen tullut."',
        39: 'Hän meni ja saarnasi heidän synagogissaan koko Galileassa ja ajoi ulos riivaajat.',
        40: 'Hänen luokseen tuli spitaalinen mies, rukoili häntä, polvistui ja sanoi hänelle: "Jos tahdot, voit puhdistaa minut."',
        41: 'Jeesuksen kävi häntä sääliksi, ja ojentaen kätensä hän kosketti häntä ja sanoi hänelle: "Minä tahdon, puhdistu."',
        42: 'Hänen sanottuaan tämän spitaali heti lähti miehestä, ja hän puhdistui.',
        43: 'Varoitettuaan ankarasti häntä hän laski hänet heti menemään',
        44: 'ja sanoi hänelle: "Katso, ettet puhu kenellekään tästä mitään, vaan mene ja näytä itsesi papille ja uhraa puhdistumisestasi se, minkä Mooses on säätänyt, todistukseksi heille."',
        45: 'Mutta mentyään pois tämä rupesi laajalti julistamaan ja levittämään asiasta tietoa, niin ettei Jeesus enää voinut julkisesti mennä kaupunkeihin, vaan oleskeli niiden ulkopuolella autioissa paikoissa, ja kaikkialta tultiin hänen luokseen.',
    },
    2: {
        1: 'Muutamien päivien kuluttua hän meni taas Kapernaumiin, ja kuultiin, että hän oli kotona.',
        2: 'Silloin kokoontui heti paljon väkeä, niin etteivät he enää mahtuneet oven edustallekaan. Hän puhui heille sanaa.',
        3: 'He olivat tulossa hänen luokseen ja tuomassa halvaantunutta, jota kantoi neljä miestä.',
        4: 'Kun he kansanjoukon tähden eivät päässeet hänen luokseen, he purkivat katon siltä kohdalta, missä hän oli, ja kaivettuaan aukon laskivat alas vuoteen, jolla halvaantunut makasi.',
        5: 'Kun Jeesus näki heidän uskonsa, hän sanoi halvaantuneelle: "Poikani, sinun syntisi ovat sinulle anteeksi annetut."',
        6: 'Mutta siellä istui muutamia kirjanoppineita, ja he ajattelivat sydämessään:',
        7: '"Kuinka tämä tällä tavalla puhuu jumalanpilkkaa! Kuka voi antaa syntejä anteeksi paitsi Jumala yksin?"',
        8: 'Heti Jeesus tunsi hengessään, että he mielessään niin ajattelivat, ja sanoi heille: "Miksi ajattelette sellaista sydämessänne?',
        9: "Kumpi on helpompaa, sanoa halvaantuneelle: 'Syntisi ovat anteeksi annetut', vai sanoa: 'Nouse, ota vuoteesi ja kävele'?",
        10: 'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi, niin" – hän sanoi halvaantuneelle –',
        11: '"sanon sinulle: nouse, ota vuoteesi ja mene kotiisi."',
        12: 'Hän nousi heti, otti vuoteensa ja meni ulos kaikkien editse, niin että kaikki hämmästyivät ja ylistivät Jumalaa sanoen: "Tällaista emme ole ikinä nähneet."',
        13: 'Hän lähti taas pois ja kulki järven rantaa. Kaikki kansa tuli hänen luokseen, ja hän opetti heitä.',
        14: 'Kulkiessaan ohi hän näki Leevin, Alfeoksen pojan, istumassa tulliasemalla ja sanoi hänelle: "Seuraa minua." Tämä nousi ja seurasi häntä.',
        15: 'Tapahtui hänen ollessaan aterialla hänen kodissaan, että myös monta publikaania ja syntistä aterioi Jeesuksen ja hänen opetuslastensa kanssa, sillä heitä oli paljon häntä seuraamassa.',
        16: 'Kun fariseukset ja kirjanoppineet näkivät, että hän söi syntisten ja publikaanien kanssa, he sanoivat hänen opetuslapsilleen: "Miksi hän syö publikaanien ja syntisten kanssa?"',
        17: 'Sen kuullessaan Jeesus sanoi heille: "Eivät terveet tarvitse parantajaa, vaan sairaat. En ole tullut kutsumaan vanhurskaita, vaan syntisiä mielenmuutokseen."',
        18: 'Johanneksen opetuslapset ja fariseusten opetuslapset paastosivat. Niin hänelle tultiin sanomaan: "Miksi Johanneksen opetuslapset ja fariseusten opetuslapset paastoavat, mutta sinun opetuslapsesi eivät paastoa?"',
        19: 'Jeesus sanoi heille: "Eiväthän häävieraat voi paastota silloin, kun ylkä on heidän kanssaan? Niin kauan kuin ylkä on heidän kanssaan, he eivät voi paastota.',
        20: 'Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin, niinä päivinä, he paastoavat.',
        21: 'Ei kukaan ompele vanuttamattomasta kankaasta paikkaa vanhaan vaatteeseen, muuten uusi paikka repii palan vanhasta vaatteesta, ja reikä tulee pahemmaksi.',
        22: 'Eikä kukaan laske nuorta viiniä vanhoihin leileihin, muuten viini halkaisee leilit, ja viini vuotaa pois, ja leilit turmeltuvat, vaan nuori viini on laskettava uusiin leileihin."',
        23: 'Tapahtui, että hän sapattina kulki viljavainioiden halki, ja hänen opetuslapsensa rupesivat kulkiessaan poimimaan tähkiä.',
        24: 'Mutta fariseukset sanoivat hänelle: "Katso, miksi he tekevät sapattina sitä, mikä ei ole luvallista?"',
        25: 'Hän sanoi heille: "Ettekö ole koskaan lukeneet, mitä Daavid teki, kun häneltä ja hänen tovereiltaan puuttui ruokaa ja heillä oli nälkä,',
        26: 'kuinka hän meni Jumalan huoneeseen ylipappi Abjatarin aikana ja söi näkyleivät, joita ei ollut lupa syödä muiden kuin pappien, ja antoi myös niille, jotka olivat hänen kanssaan?"',
        27: 'Hän sanoi heille: "Sapatti on ihmistä varten eikä ihminen sapattia varten.',
        28: 'Niinpä Ihmisen Poika on sapatinkin herra."',
    },
    3: {
        1: 'Hän meni taas synagogaan, ja siellä oli mies, jonka käsi oli kuivettunut.',
        2: 'He pitivät häntä silmällä, parantaisiko hän miehen sapattina, voidakseen nostaa syytteen häntä vastaan.',
        3: 'Hän sanoi miehelle, jonka käsi oli kuivettunut: "Nouse ja asetu esiin tähän keskelle."',
        4: 'Sitten hän sanoi heille: "Kumpi on luvallista sapattina: tehdä hyvää vai tehdä pahaa, pelastaa sielu vai tappaa se?" Mutta he olivat vaiti.',
        5: 'Silloin hän katsahtaen ympärilleen loi vihassa silmänsä heihin murheellisena heidän sydämensä paatumuksen tähden, ja sanoi miehelle: "Ojenna kätesi." Ja hän ojensi, ja hänen kätensä tuli ennalleen, terveeksi, kuten toinen käsi.',
        6: 'Mutta fariseukset lähtivät pois ja pitivät heti herodeslaisten kanssa neuvottelun häntä vastaan surmatakseen hänet.',
        7: 'Mutta Jeesus vetäytyi opetuslapsineen järven rannalle, ja häntä seurasi suuri joukko kansaa Galileasta. Myös Juudeasta,',
        8: 'Jerusalemista, Idumeasta, Jordanin tuolta puolen ja Tyyron ja Siidonin ympäristöstä tuli paljon kansaa hänen luokseen, kun he kuulivat, kuinka suuria tekoja hän teki.',
        9: 'Hän sanoi opetuslapsilleen, että hänelle oli pidettävä vene varalla kansanjoukon tähden, ettei se ahdistaisi häntä.',
        10: 'Sillä hän paransi monta, jonka tähden kaikki, joilla oli vaivoja, tungeksivat hänen päälleen koskettaakseen häntä.',
        11: 'Kun saastaiset henget näkivät hänet, ne lankesivat hänen eteensä ja huusivat sanoen: "Sinä olet Jumalan Poika."',
        12: 'Hän varoitti niitä ankarasti saattamasta häntä ilmi.',
        13: 'Hän nousi vuorelle ja kutsui luokseen ne, jotka hän itse tahtoi, ja he menivät hänen luokseen.',
        14: 'Hän asetti kaksitoista olemaan kanssaan ja lähettääkseen heidät saarnaamaan,',
        15: 'ja heillä oli oleva valta parantaa sairauksia ja ajaa ulos riivaajia.',
        16: 'Nämä kaksitoista hän asetti: Simonin, jolle hän antoi nimen Pietari,',
        17: 'Jaakobin, Sebedeuksen pojan, Johanneksen, Jaakobin veljen, joille hän antoi nimen Boanerges, se on: ukkosenjylinän pojat,',
        18: 'Andreaan, Filippoksen, Bartolomeoksen, Matteuksen, Tuomaan, Jaakobin, Alfeoksen pojan, Taddeuksen, Simon Kananeuksen',
        19: 'ja Juudas Iskariotin, saman, joka hänet kavalsi.',
        20: 'Sitten hän meni kotiin. Taas kokoontui paljon kansaa, niin etteivät he voineet syödäkään.',
        21: 'Kun hänen omaisensa sen kuulivat, he menivät ottamaan häntä huostaansa, sillä he sanoivat: "Hän on poissa tolaltaan."',
        22: 'Mutta kirjanoppineet, jotka olivat tulleet Jerusalemista, sanoivat: "Hänessä on Beelsebul", ja: "riivaajien päämiehen avulla hän ajaa ulos riivaajia."',
        23: 'Hän kutsui heidät luokseen ja sanoi heille vertauksilla: "Kuinka saatana voi ajaa ulos saatanan?',
        24: 'Jos jokin valtakunta riitautuu itsensä kanssa, sellainen valtakunta ei voi pysyä pystyssä.',
        25: 'Jos talo riitautuu itsensä kanssa, sellainen talo ei voi pysyä pystyssä.',
        26: 'Jos saatana nousee itseään vastaan ja riitautuu itsensä kanssa, hän ei voi pysyä, vaan hänen loppunsa on tullut.',
        27: 'Kukaan ei voi tunkeutua väkevän taloon ja ryöstää hänen tavaraansa, ellei hän ensin sido sitä väkevää ja vasta sitten ryöstä hänen taloaan.',
        28: 'Totisesti sanon teille: kaikki synnit annetaan ihmisten lapsille anteeksi, jumalanpilkatkin, kuinka paljon pilkannevatkin.',
        29: 'Mutta se, joka pilkkaa Pyhää Henkeä, ei saa ikinä anteeksi, vaan on syypää iankaikkiseen syntiin."',
        30: 'Sillä he sanoivat: "Hänessä on saastainen henki."',
        31: 'Hänen äitinsä ja veljensä tulivat, seisahtuivat ulkopuolelle ja lähettivät [erään miehen] hänen luokseen kutsumaan häntä.',
        32: 'Kansanjoukko istui hänen ympärillään, ja he sanoivat hänelle: "Katso, äitisi ja veljesi ulkona kysyvät sinua."',
        33: 'Hän vastasi heille sanoen: "Kuka on minun äitini, ja ketkä ovat minun veljiäni?"',
        34: 'Katsellen ympärilleen niihin, jotka istuivat hänen ympärillään, hän sanoi: "Katso, äitini ja veljeni!',
        35: 'Sillä se, joka tekee Jumalan tahdon, on veljeni, sisareni ja äitini."',
    },
    4: {
        1: 'Sitten hän rupesi taas opettamaan järven rannalla. Hänen luokseen kokoontui paljon kansaa, jonka tähden hän astuttuaan veneeseen istui siinä järvellä, ja kaikki kansa oli maalla järven rannalla.',
        2: 'Hän opetti heitä monilla vertauksilla ja sanoi heille opettaessaan:',
        3: '"Kuulkaa! Katso, kylväjä lähti kylvämään.',
        4: 'Tapahtui hänen kylväessään, että osa putosi tien vierelle, ja taivaan linnut tulivat ja söivät sen.',
        5: 'Osa putosi kallioiselle paikalle, jossa sillä ei ollut paljon maata, ja se nousi heti oraalle, koska sillä ei ollut syvää maata.',
        6: 'Mutta auringon noustua se paahtui, ja kun sillä ei ollut juurta, se kuivui.',
        7: 'Osa putosi orjantappuroihin, ja orjantappurat nousivat ja tukahduttivat sen, eikä se tehnyt hedelmää.',
        8: 'Mutta osa putosi hyvään maahan, nousi oraalle, kasvoi, antoi sadon ja tuotti mikä kolmekymmentä-, mikä kuusikymmentä- ja mikä satakertaisen sadon."',
        9: 'Hän sanoi: "Jolla on korvat kuulla, se kuulkoon."',
        10: 'Kun hän oli yksin, niin ne, jotka olivat hänen ympärillään, sekä ne kaksitoista kysyivät häneltä tästä vertauksesta.',
        11: 'Hän sanoi heille: "Teille on annettu tuntea Jumalan valtakunnan salaisuus, mutta noille ulkopuolella oleville kaikki tulee vertauksissa,',
        12: 'että he näkisivät näkemällä, eivätkä huomaisi, ja kuulisivat kuulemalla, eivätkä ymmärtäisi, etteivät kääntyisi ja saisi anteeksi."',
        13: 'Hän sanoi heille: "Jos ette käsitä tätä vertausta, kuinka sitten voitte ymmärtää kaikki muut vertaukset?',
        14: 'Kylväjä kylvää sanan.',
        15: 'Mitkä tien vierelle putosivat, ovat niitä, joihin sana kylvetään, mutta kun he sen kuulevat, saatana tulee heti ja ottaa pois heihin kylvetyn sanan.',
        16: 'Mitkä kalliolle kylvettiin, ovat ne, jotka, kun kuulevat sanan, ottavat sen heti ilolla vastaan,',
        17: 'mutta heillä ei ole juurta itsessään, vaan he kestävät ainoastaan jonkin aikaa. Kun sitten tulee ahdistus tai vaino sanan tähden, he heti lankeavat pois.',
        18: 'Toisia ovat orjantappuroihin kylvetyt. Nämä ovat niitä, jotka kuulevat sanan,',
        19: 'mutta tämän maailman huolet ja rikkauden petollisuus ja muut himot pääsevät valtaan ja tukahduttavat sanan, ja se jää hedelmättömäksi.',
        20: 'Mitkä hyvään maahan kylvettiin, ovat niitä, jotka kuulevat sanan ja ottavat sen vastaan ja kantavat hedelmän, mikä kolmekymmentä-, mikä kuusikymmentä-, mikä satakertaisen."',
        21: 'Hän sanoi heille: "Eihän lamppua oteta esiin pantavaksi vakan alle tai vuoteen alle? Eikö lampunjalkaan pantavaksi?',
        22: 'Sillä ei mikään ole salattua muuta varten, kuin jotta se tulisi ilmi, eikä kätkettynä muuta varten kuin tullakseen ilmi.',
        23: 'Jos jollakulla on korvat kuulla, kuulkoon."',
        24: 'Hän sanoi heille: "Katsokaa, mitä kuulette. Millä mitalla mittaatte, sillä teille mitataan, vieläpä teille, jotka tämän kuulette, lisätäänkin.',
        25: 'Sillä sille, jolla on, annetaan, mutta siltä, jolla ei ole, otetaan pois sekin, mitä hänellä on."',
        26: 'Hän sanoi: "Niin on Jumalan valtakunta, kuin jos mies kylvää siemenen maahan,',
        27: 'ja hän nukkuu, ja hän nousee, öin ja päivin, ja siemen orastaa ja kasvaa, hän ei itse tiedä, miten.',
        28: 'Sillä itsestään maa tuottaa viljan: ensin korren, sitten tähkän, sitten täyden jyvän tähkään.',
        29: 'Mutta kun vilja on tuleentunut, hän lähettää heti sinne sirpin, sillä korjuuaika on käsillä."',
        30: 'Hän sanoi: "Mihin vertaamme Jumalan valtakunnan, eli mitä vertausta siitä käytämme?',
        31: 'Se on kuin sinapinsiemen, joka, kun se kylvetään maahan, on pienin kaikista kylvösiemenistä maan päällä.',
        32: 'Mutta kun se on kylvetty, se nousee ja tulee suurimmaksi kaikista puutarhakasveista ja tekee suuria oksia, niin että taivaan linnut voivat tehdä pesänsä sen varjoon."',
        33: 'Monilla tällaisilla vertauksilla hän puhui heille sanaa, sen mukaan kuin he kykenivät kuulemaan,',
        34: 'ja ilman vertausta hän ei puhunut heille. Mutta opetuslapsilleen hän selitti kaikki, kun he olivat muista erillään.',
        35: 'Sinä päivänä hän illan tultua sanoi heille: "Lähtekäämme yli toiselle rannalle."',
        36: 'Niin he laskivat kansan luotaan ja ottivat hänet mukaansa hänen ollessaan jo veneessä, ja muitakin veneitä oli hänen seurassaan.',
        37: 'Nousi kova myrskytuuli, ja aallot syöksyivät yli veneeseen, niin että se jo täyttyi.',
        38: 'Mutta itse hän oli veneen perällä ja nukkui nojaten päänaluseen. Niin he herättivät hänet ja sanoivat hänelle: "Opettaja, etkö välitä siitä, että hukumme?"',
        39: 'Herättyään hän nuhteli tuulta ja sanoi järvelle: "Vaikene, ole hiljaa." Tuuli asettui, ja tuli suuri tyyneys.',
        40: 'Hän sanoi heille: "Miksi olette sillä tavoin pelkureita? Kuinka teillä ei ole uskoa?"',
        41: 'Suuri pelko valtasi heidät, ja he sanoivat toisilleen: "Kuka tämä onkaan, kun sekä tuuli että meri häntä tottelevat?"',
    },
    5: {
        1: 'He tulivat järven toiselle puolelle gadaralaisten alueelle.',
        2: 'Hänen lähdettyään veneestä häntä vastaan tuli heti haudoista mies, joka oli saastaisen hengen vallassa.',
        3: 'Hän piti asuntoaan haudoissa, eikä kukaan enää voinut sitoa häntä kahleillakaan.',
        4: 'Sillä hänet oli monta kertaa sidottu jalkanuoriin ja kahleisiin, mutta hän oli särkenyt kahleet ja katkonut jalkanuorat, eikä kukaan kyennyt häntä hillitsemään.',
        5: 'Hän oleskeli aina yötä päivää vuorilla ja haudoissa huutaen ja runnellen itseään kivillä.',
        6: 'Kun hän näki Jeesuksen kaukaa, hän juoksi ja kumartui hänen eteensä',
        7: 'ja huutaen suurella äänellä sanoi: "Mitä sinulla on minun kanssani tekemistä, Jeesus, Jumalan, Korkeimman, Poika? Vannotan sinua Jumalan kautta, älä vaivaa minua."',
        8: 'Sillä hän oli sanomaisillaan sille: "Lähde ulos miehestä, sinä, saastainen henki."',
        9: 'Jeesus kysyi siltä: "Mikä on nimesi?" Se vastasi hänelle ja sanoi hänelle: "Legioona on nimeni, sillä meitä on monta."',
        10: 'Se pyysi pyytämällä häneltä, ettei hän lähettäisi niitä pois siltä seudulta.',
        11: 'Niin siellä oli vuoren rinteellä suuri sikalauma laitumella.',
        12: 'Kaikki riivaajat pyysivät häntä sanoen: "Lähetä meidät sikoihin, jotta menisimme niihin."',
        13: 'Hän salli sen niille. Saastaiset henget lähtivät miehestä ja menivät sikoihin. Silloin lauma, noin kaksituhatta sikaa, syöksyi jyrkännettä alas järveen, ja ne hukkuivat järveen.',
        14: 'Mutta sikopaimenet pakenivat ja kertoivat siitä kaupungissa ja maalla, ja kansa lähti katsomaan, mitä oli tapahtunut.',
        15: 'He tulivat Jeesuksen luo ja näkivät riivatun, jossa oli ollut legioona riivaajia, istuvan puettuna ja järjissään, ja he pelästyivät.',
        16: 'Näkijät kertoivat näille, mitä oli tapahtunut riivatulle ja kuinka sikojen oli käynyt.',
        17: 'Niin ihmiset alkoivat pyytää häntä poistumaan heidän alueeltaan.',
        18: 'Hänen astuessaan veneeseen riivaajien vallassa ollut pyysi häneltä saada olla hänen kanssaan.',
        19: 'Mutta Jeesus ei sallinut sitä, vaan sanoi hänelle: "Mene kotiisi omaistesi luo ja kerro heille, kuinka suuria tekoja Herra on sinulle tehnyt ja kuinka hän on sinua armahtanut."',
        20: 'Hän lähti ja rupesi Dekapolin alueella julistamaan, kuinka suuria tekoja Jeesus oli hänelle tehnyt, ja kaikki ihmettelivät.',
        21: 'Kun Jeesus oli veneellä kulkenut takaisin toiselle puolelle, paljon kansaa kokoontui hänen luokseen, ja hän oli järven rannalla.',
        22: 'Katso, muuan synagogan esimies, nimeltä Jairos, tuli ja lankesi hänet nähdessään hänen jalkojensa juureen,',
        23: 'pyysi häntä hartaasti ja sanoi: "Pieni tyttäreni on kuolemaisillaan, tule ja pane kätesi hänen päälleen, jotta hän tulisi terveeksi ja jäisi eloon."',
        24: 'Hän lähti hänen kanssaan. Häntä seurasi suuri kansan paljous, ja he tunkeutuivat hänen ympärilleen.',
        25: 'Siellä oli nainen, joka oli sairastanut verenjuoksua kaksitoista vuotta',
        26: 'ja paljon kärsinyt monen lääkärin käsissä ja kuluttanut kaiken omaisuutensa saamatta mitään apua, pikemminkin käyden huonommaksi.',
        27: 'Tämä oli kuullut Jeesuksesta ja tuli kansanjoukossa takaapäin ja koski hänen viittaansa,',
        28: 'sillä hän sanoi: "Jos vain kosken hänen vaatteisiinsa, tulen terveeksi."',
        29: 'Heti hänen verensä lähde kuivui, ja hän tunsi ruumiissaan, että oli parantunut vaivastaan.',
        30: 'Heti kun Jeesus tunsi itsessään, että voimaa oli lähtenyt hänestä, hän kääntyi väkijoukossa ja sanoi: "Kuka koski vaatteisiini?"',
        31: 'Hänen opetuslapsensa sanoivat hänelle: "Sinä näet kansanjoukon tungeskelevan ympärilläsi ja sanot: \'Kuka minuun koski?"',
        32: 'Mutta hän katseli ympärilleen nähdäkseen, kuka sen oli tehnyt.',
        33: 'Nainen pelkäsi ja vapisi, koska hän tiesi, mitä hänelle oli tapahtunut, ja tuli, lankesi maahan hänen eteensä ja sanoi hänelle koko totuuden.',
        34: 'Mutta Jeesus sanoi hänelle: "Tyttäreni, sinun uskosi on tehnyt sinut terveeksi. Mene rauhaan ja ole terve vaivastasi."',
        35: 'Hänen vielä puhuessaan tultiin sanomaan synagogan esimiehen kotoa: "Tyttäresi kuoli, miksi enää opettajaa vaivaat?"',
        36: 'Mutta Jeesus kuuli heti, mitä puhuttiin, ja sanoi synagogan esimiehelle: "Älä pelkää, usko ainoastaan."',
        37: 'Hän ei sallinut kenenkään muun seurata mukanaan kuin Pietarin, Jaakobin ja Johanneksen, Jaakobin veljen.',
        38: 'He tulivat synagogan esimiehen taloon, ja hän näki hälisevän joukon sekä itkeviä ja suureen ääneen vaikeroivia.',
        39: 'Käydessään sisään hän sanoi heille: "Miksi hälisette ja itkette? Lapsi ei ole kuollut, vaan nukkuu."',
        40: 'He nauroivat hänelle. Mutta hän ajoi kaikki ulos ja otti mukaansa lapsen isän ja äidin sekä ne, jotka olivat hänen kanssaan, ja meni sisälle sinne, missä lapsi makasi.',
        41: 'Hän tarttui lapsen käteen ja sanoi hänelle: "Talita kuum!" Se on käännettynä: Tyttö, sanon sinulle, nouse.',
        42: 'Heti tyttö nousi ja käveli. Sillä hän oli kaksitoistavuotias. Ja he joutuivat suuren hämmästyksen valtaan.',
        43: 'Hän kielsi kovasti heitä antamasta kenellekään tietoa tästä ja käski antaa hänelle syötävää.',
    },
    6: {
        1: 'Hän lähti sieltä ja meni kotikaupunkiinsa, ja hänen opetuslapsensa seurasivat häntä.',
        2: 'Kun sapatti oli tullut, hän alkoi opettaa synagogassa. Häntä kuunnellessaan monet hämmästyivät ja sanoivat: "Mistä tällä on kaikki tämä, ja mikä on se viisaus, joka on hänelle annettu? Mitä ovat sellaiset voimalliset teot, jotka tapahtuvat hänen kättensä kautta?',
        3: 'Eikö tämä ole se rakentaja, Marian poika ja Jaakobin, Jooseen, Juudaan ja Simonin veli? Eivätkö hänen sisarensa ole täällä meidän parissamme?" Ja he loukkaantuivat häneen.',
        4: 'Jeesus sanoi heille: "Profeetta ei ole halveksittu muualla kuin kotikaupungissaan, sukulaistensa kesken ja kodissaan."',
        5: 'Eikä hän voinut tehdä siellä yhtään voimallista tekoa, paitsi että paransi joitakuita harvoja sairaita panemalla kätensä heidän päälleen.',
        6: 'Hän ihmetteli heidän epäuskoaan. Hän kulki ympäristön kylät ja opetti.',
        7: 'Hän kutsui ne kaksitoista ja alkoi lähettää heitä kaksittain ja antoi heille vallan saastaisiin henkiin.',
        8: 'Hän sääti heille, etteivät saaneet ottaa matkalle kuin yhden sauvan, ei leipää, ei laukkua eikä rahaa vyöhön.',
        9: 'He saivat kuitenkin sitoa sandaalit jalkaansa, mutta eivät pukea kahta paitaa päälleen.',
        10: 'Hän sanoi heille: "Missä tulette taloon, jääkää sinne, kunnes lähdette pois siltä paikkakunnalta.',
        11: 'Missä teitä ei oteta vastaan eikä teitä kuulla, menkää sieltä pois ja pudistakaa tomu jalkojenne alta todistukseksi heille. Totisesti sanon teille: Helpompi on Sodoman tai Gomorran olla tuomiopäivänä kuin tuon kaupungin."',
        12: 'He lähtivät ja saarnasivat, jotta nuo muuttaisivat mielensä.',
        13: 'He ajoivat ulos monta riivaajaa ja voitelivat monta sairasta öljyllä ja paransivat heidät.',
        14: 'Kuningas Herodes sai kuulla hänestä, sillä hänen nimensä oli tullut tunnetuksi, ja hän sanoi: "Johannes Kastaja on noussut kuolleista, ja sen tähden nämä voimat vaikuttavat hänessä."',
        15: 'Mutta toiset sanoivat: "Se on Elia." Toiset taas sanoivat: "Se on profeetta, niin kuin joku profeetoista."',
        16: 'Mutta kun Herodes sen kuuli, hän sanoi: "Johannes, jonka mestautin, on noussut kuolleista."',
        17: 'Sillä hän, Herodes, oli lähettänyt ottamaan kiinni Johanneksen, sitonut ja pannut hänet vankilaan veljensä Filippoksen vaimon, Herodiaan, tähden. Sillä Herodes oli nainut hänet,',
        18: 'ja Johannes oli sanonut Herodekselle: "Sinun ei ole lupa pitää veljesi vaimoa."',
        19: 'Herodias piti vihaa häntä vastaan ja tahtoi tappaa hänet, mutta ei voinut.',
        20: 'Sillä Herodes pelkäsi Johannesta, koska tiesi hänet vanhurskaaksi ja pyhäksi mieheksi, ja suojeli häntä. Hän teki monia asioita, joita hän häneltä kuuli, ja kuunteli häntä mielellään.',
        21: 'Niin tuli sopiva päivä, kun Herodes syntymäpäivänään piti pitoja ylimyksilleen, tuhannenpäälliköille ja Galilean ensimmäisille miehille.',
        22: 'Herodiaan tytär tuli sisälle ja tanssi, ja se miellytti Herodesta ja hänen pöytävieraitaan. Kuningas sanoi tytölle: "Ano minulta, mitä ikinä tahdot, niin annan sinulle."',
        23: 'Hän vannoi tytölle: "Mitä ikinä minulta anot, sen annan sinulle, vaikka puolet valtakuntaani."',
        24: 'Hän meni ulos ja sanoi äidilleen: "Mitä pyydän?" Tämä sanoi: "Johannes Kastajan päätä."',
        25: 'Hän meni heti kiireen vilkkaa sisälle kuninkaan luo, pyysi ja sanoi: "Tahdon, että nyt heti annat minulle lautasella Johannes Kastajan pään."',
        26: 'Silloin kuningas tuli hyvin murheelliseksi, mutta valansa ja pöytävieraiden tähden hän ei tahtonut hylätä hänen pyyntöään.',
        27: 'Heti kuningas lähetti pyövelin ja käski tuoda Johanneksen pään.',
        28: 'Pyöveli lähti ja löi häneltä pään poikki vankilassa ja toi hänen päänsä lautasella ja antoi sen tytölle, ja tyttö antoi sen äidilleen.',
        29: 'Kun hänen opetuslapsensa sen kuulivat, he tulivat ja ottivat hänen ruumiinsa ja panivat sen hautaan.',
        30: 'Apostolit kokoontuivat Jeesuksen luo ja kertoivat hänelle kaikki, mitä olivat tehneet ja mitä opettaneet.',
        31: 'Hän sanoi heille: "Tulkaa te yksinäisyyteen, autioon paikkaan, ja levähtäkää vähän." Sillä tulijoita ja menijöitä oli paljon, ja heillä ei ollut aikaa edes syödä.',
        32: 'He lähtivät veneellä autioon paikkaan, yksinäisyyteen.',
        33: 'Heidän nähtiin lähtevän, ja monet saivat siitä tiedon ja tulivat sinne juoksujalkaa kaikista kaupungeista ja saapuivat ennen heitä.',
        34: 'Astuessaan maihin hän näki paljon kansaa, ja hänen kävi heitä sääliksi, koska he olivat kuin lampaat ilman paimenta, ja hän rupesi opettamaan heille monia asioita.',
        35: 'Kun päivä oli jo kulunut pitkälle, hänen opetuslapsensa menivät hänen luokseen ja sanoivat: "Tämä paikka on autio, ja on jo myöhäinen ilta.',
        36: 'Laske heidät luotasi, että he menisivät ympäristöllä oleviin maataloihin ja kyliin ostamaan itselleen syötävää, sillä heillä ei ole mitä syödä."',
        37: 'Mutta hän vastasi heille ja sanoi: "Antakaa te heille syödä." Niin he sanoivat hänelle: "Lähdemmekö ostamaan leipää kahdellasadalla denaarilla antaaksemme heille syödä?"',
        38: 'Mutta hän sanoi heille: "Montako leipää teillä on? Menkää katsomaan." Otettuaan siitä selvän he sanoivat: "Viisi, ja kaksi kalaa."',
        39: 'Hän määräsi heille, että kaikkien oli asetuttava ruokakunnittain vihantaan ruohikkoon.',
        40: 'He laskeutuivat ryhmä ryhmän viereen, toisiin sata, toisiin viisikymmentä.',
        41: 'Hän otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen, siunasi, mursi leivät ja antoi ne opetuslapsilleen kansan eteen pantaviksi, myös ne kaksi kalaa hän jakoi kaikille.',
        42: 'Kaikki söivät ja tulivat ravituiksi.',
        43: 'He keräsivät palaset, kaksitoista täyttä korillista, ja tähteet kaloista.',
        44: 'Niitä, jotka olivat syöneet näitä leipiä, oli viisituhatta miestä.',
        45: 'Heti hän vaati opetuslapsiaan astumaan veneeseen ja kulkemaan edeltä toiselle rannalle Beetsaidaan, sillä aikaa kun hän laskisi kansan luotaan.',
        46: 'Erottuaan heistä hän meni pois vuorelle rukoilemaan.',
        47: 'Mutta kun ilta tuli, vene oli keskellä järveä, ja hän oli yksin maissa.',
        48: 'Kun hän näki heidän soutaessaan olevan hädässä, sillä tuuli oli heille vastainen, hän tuli neljännen yövartion vaiheilla heidän luokseen kävellen järven päällä ja aikoi kulkea heidän ohitseen.',
        49: 'Mutta nähdessään hänen kävelevän järven päällä he luulivat häntä aaveeksi ja alkoivat huutaa,',
        50: 'sillä kaikki näkivät hänet ja pelästyivät. Mutta heti hän puhutteli heitä ja sanoi heille: "Olkaa turvallisella mielellä, Minä olen, älkää pelätkö."',
        51: 'Hän astui veneeseen heidän luokseen, ja tuuli asettui. He hämmästyivät aivan suunnattomasti sisimmässään.',
        52: 'Sillä he eivät olleet noista leivistäkään päässeet ymmärrykseen, vaan heidän sydämensä oli paatunut.',
        53: 'Päästyään yli toiselle rannalle he tulivat Genetsaretiin ja laskivat maihin.',
        54: 'Heidän noustessaan veneestä kansa heti tunsi hänet,',
        55: 'ja he riensivät kiertämään koko sitä paikkakuntaa ja ryhtyivät vuoteilla kantamaan sairaita sinne, missä kuulivat hänen olevan.',
        56: 'Missä vain hän meni kyliin, kaupunkeihin tai maataloihin, asetettiin sairaat aukeille paikoille ja pyydettiin häneltä, että he saisivat koskea edes hänen viittansa tupsuun. Kaikki, jotka koskivat häneen, tulivat terveiksi.',
    },
    7: {
        1: 'Mutta fariseukset ja muutamat kirjanoppineet, jotka olivat tulleet Jerusalemista, kokoontuivat hänen luokseen.',
        2: 'He näkivät, että muutamat hänen opetuslapsistaan söivät leipää epäpuhtain, se on pesemättömin, käsin.',
        3: 'Sillä eivät fariseukset eivätkä ketkään juutalaiset syö, ennen kuin ovat pesseet tarkasti kätensä, noudattaen vanhinten perinnäissääntöä,',
        4: 'ja torilta tultuaan he eivät syö, ennen kuin ovat itseään vedellä vihmoneet. On paljon muutakin, mitä he ovat ottaneet noudattaakseen, kuten maljojen, kiviastioiden, vaskiastioiden ja vuoteiden pesemisiä.',
        5: 'Fariseukset ja kirjanoppineet kysyivät häneltä: "Miksi sinun opetuslapsesi eivät vaella vanhinten perinnäissäännön mukaan, vaan syövät leipää epäpuhtain käsin?"',
        6: 'Mutta hän sanoi heille: "Oikein Jesaja on ennustanut teistä, tekopyhistä, kuten on kirjoitettu: \'Tämä kansa kunnioittaa minua huulillaan, mutta heidän sydämensä on minusta kaukana,',
        7: "mutta turhaan he palvelevat minua opettaen oppeja, jotka ovat ihmiskäskyjä.'",
        8: 'Hylkäätte Jumalan käskyn ja noudatatte ihmisten perinnäissääntöä."',
        9: 'Hän sanoi heille: "Taitavasti hylkäätte Jumalan käskyn noudattaaksenne omaa perinnäissääntöänne.',
        10: "Sillä Mooses on sanonut: 'Kunnioita isääsi ja äitiäsi', ja: 'Joka kiroaa isäänsä tai äitiään, sen pitää kuolemalla kuoleman.'",
        11: "Mutta te sanotte, että jos ihminen sanoo isälleen tai äidilleen: 'Se, minkä olisit saava minulta hyväksesi, on korban' – se on uhrilahja –",
        12: 'ettekä enää salli hänen antaa mitään isälleen tai äidilleen.',
        13: 'Teette Jumalan sanan tyhjäksi perinnäissäännöllänne, jonka olette säätäneet. Paljon muuta samanlaista teette."',
        14: 'Hän kutsui taas kaiken kansan luokseen ja sanoi heille: "Kuulkaa minua kaikki ja ymmärtäkää:',
        15: 'ei mikään, mikä menee ihmisen ulkopuolelta hänen sisäänsä, voi häntä saastuttaa, vaan se, mikä lähtee hänestä ulos, saastuttaa ihmisen.',
        16: 'Jos jollakulla on korvat kuulla, kuulkoon."',
        17: 'Kun hän lähdettyään kansan luota oli mennyt erääseen taloon, hänen opetuslapsensa kysyivät häneltä tätä vertausta.',
        18: 'Hän sanoi heille: "Niinkö ymmärtämättömiä tekin olette? Ettekö käsitä, ettei mikään, mikä ulkoapäin menee ihmiseen, voi häntä saastuttaa?',
        19: 'Sillä se ei mene hänen sydämeensä, vaan vatsaan, ja ulostetaan käymälään." Näin hän puhdisti kaikki ruuat.',
        20: 'Hän sanoi: "Mikä ihmisestä lähtee ulos, se saastuttaa ihmisen.',
        21: 'Sillä sisästä, ihmisten sydämestä, lähtevät pahat ajatukset, aviorikokset, haureudet, murhat,',
        22: 'varkaudet, ahneus, häijyys, petollisuus, irstaus, kateus, jumalanpilkka, ylpeys, mielettömyys.',
        23: 'Kaikki tämä paha lähtee sisästä ulos ja saastuttaa ihmisen."',
        24: 'Hän nousi ja lähti sieltä Tyyron ja Siidonin alueelle. Hän meni erääseen taloon eikä tahtonut, että kukaan saisi sitä tietää, mutta hän ei saanut olla salassa,',
        25: 'vaan heti kun eräs nainen, jonka pienessä tyttäressä oli saastainen henki, kuuli hänestä, nainen tuli ja lankesi hänen jalkojensa juureen.',
        26: 'Mutta nainen oli kreikatar, syntyperältään syyrialaisfoinikialainen, ja hän pyysi häntä ajamaan riivaajan pois tyttärestään.',
        27: 'Jeesus vastasi ja sanoi hänelle: "Salli lasten tulla ensin ravituiksi, sillä ei ole hyvä ottaa lasten leipää ja heittää koiranpenikoille."',
        28: 'Mutta hän vastasi ja sanoi hänelle: "Niin, Herra, mutta syöväthän penikatkin pöydän alta lasten muruja."',
        29: 'Hän sanoi naiselle: "Tämän sanan tähden, mene, riivaaja on lähtenyt tyttärestäsi."',
        30: 'Nainen meni kotiinsa ja havaitsi lapsen makaavan vuoteella ja riivaajan lähteneen hänestä.',
        31: 'Hän [Jeesus] lähti jälleen Tyyron ja Siidonin alueelta ja tuli Galilean järven rannalta ylös Dekapolin alueen keskelle.',
        32: 'Hänen luokseen tuotiin kuuro, joka puhui epäselvästi, ja he pyysivät häntä panemaan kätensä hänen päälleen.',
        33: 'Niin hän otti hänet erilleen kansasta, pisti sormensa hänen korviinsa, sylki ja koski hänen kieleensä',
        34: 'ja katsoi ylös taivaaseen, huokasi ja sanoi hänelle: "Effata", se on: aukene.',
        35: 'Hänen korvansa aukenivat heti, ja hänen kielensä side irtautui, ja hän puhui oikein.',
        36: 'Jeesus kielsi heitä sitä kenellekään sanomasta. Mutta mitä enemmän hän heitä kielsi, sitä enemmän he julistivat.',
        37: 'Ihmiset hämmästyivät suunnattomasti ja sanoivat: "Hyvin hän on kaikki tehnyt: kuurot hän saa kuulemaan ja mykät puhumaan."',
    },
    8: {
        1: 'Niinä päivinä, kun kansaa oli taas koolla varsin paljon eikä heillä ollut mitään syötävää, hän kutsui opetuslapsensa luokseen ja sanoi heille:',
        2: '"Minun käy sääliksi kansaa, sillä he ovat jo kolme päivää olleet luonani, eikä heillä ole mitä syödä.',
        3: 'Jos minä lasken heidät menemään syömättä kotiinsa, he nääntyvät matkalla, sillä muutamat heistä ovat tulleet kaukaa."',
        4: 'Hänen opetuslapsensa vastasivat hänelle: "Mistä täällä erämaassa kukaan voi saada leipää näiden ravitsemiseksi?"',
        5: 'Hän kysyi heiltä: "Montako leipää teillä on?" He sanoivat: "Seitsemän."',
        6: 'Silloin hän käski kansan asettua maahan. Hän otti ne seitsemän leipää, kiitti, mursi ja antoi opetuslapsilleen, että he jakaisivat ne. He jakoivat ne kansalle.',
        7: 'Heillä oli myös joitakin pieniä kaloja, ja siunattuaan ne hän käski jakaa nekin.',
        8: 'He söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, seitsemän korillista.',
        9: 'Heitä oli noin neljätuhatta. Hän laski heidät luotaan.',
        10: 'Heti hän astui opetuslapsineen veneeseen ja meni Dalmanutan seuduille.',
        11: 'Fariseukset lähtivät sinne ja rupesivat väittelemään hänen kanssaan ja vaativat häneltä merkkiä taivaasta kiusaten häntä.',
        12: 'Hän huokasi hengessään ja sanoi: "Miksi tämä sukukunta vaatii merkkiä? Totisesti minä sanon teille: tälle sukukunnalle ei anneta merkkiä."',
        13: 'Hän jätti heidät ja astui taas veneeseen ja lähti pois toiselle rannalle.',
        14: 'Mutta opetuslapset olivat unohtaneet ottaa mukaansa leipää, eikä heillä ollut mukanaan veneessä kuin yksi leipä.',
        15: 'Hän käski heitä sanoen: "Varokaa ja kavahtakaa fariseusten hapatusta ja Herodeksen hapatusta."',
        16: 'He puhelivat keskenään ja sanoivat: "Meillä ei ole leipää."',
        17: 'Kun Jeesus huomasi sen, hän sanoi heille: "Mitä puhelette siitä, ettei teillä ole leipää? Ettekö vielä käsitä ettekä ymmärrä? Onko teidän sydämenne paatunut?',
        18: 'Silmät teillä on, ettekö näe? Korvat teillä on, ettekö kuule? Ettekö muista:',
        19: 'kun minä mursin ne viisi leipää viidelletuhannelle, kuinka monta täyttä korillista palasia te keräsitte?" He sanoivat hänelle: "Kaksitoista."',
        20: '"Kun minä mursin ne seitsemän neljälletuhannelle, kuinka monta täyttä korillista palasia te keräsitte?" He sanoivat: "Seitsemän."',
        21: 'Hän sanoi heille: "Ettekö vieläkään ymmärrä?"',
        22: 'He tulivat Beetsaidaan. Hänen luokseen tuotiin sokea, ja he pyysivät, että hän koskisi häneen.',
        23: 'Hän tarttui sokean käteen, talutti hänet kylän ulkopuolelle, sylki hänen silmiinsä ja pani kätensä hänen päälleen ja kysyi häneltä, näkikö hän jotakin.',
        24: 'Tämä katsoi ylös ja sanoi: "Näen ihmisten kävelevän, he ovat kuin puita."',
        25: 'Hän pani kätensä taas hänen silmilleen ja teki hänet näkeväksi. Hän oli tullut jälleen terveeksi ja näki kaiken selvästi.',
        26: 'Hän lähetti hänet hänen kotiinsa sanoen: "Älä poikkea kylään äläkä kerro kenellekään kylässä."',
        27: 'Jeesus lähti opetuslapsineen Filippoksen Kesarean kyliin. Tiellä hän kysyi opetuslapsiltaan ja sanoi heille: "Kenen ihmiset sanovat minun olevan?"',
        28: 'He vastasivat hänelle sanoen: "Johannes Kastajan, ja toiset Eliaan, toiset taas jonkun profeetoista."',
        29: 'Hän sanoi heille: "Kenen te sanotte minun olevan?" Pietari vastasi ja sanoi hänelle: "Sinä olet Kristus."',
        30: 'Hän varoitti heitä puhumasta kenellekään hänestä.',
        31: 'Hän alkoi opettaa heille, että Ihmisen Pojan pitää paljon kärsiä ja joutua vanhinten, ylipappien ja kirjanoppineiden hylkimäksi ja tapetuksi, mutta kolmen päivän kuluttua hän on nouseva ylös.',
        32: 'Tämän hän puhui peittelemättä. Silloin Pietari otti hänet erilleen ja alkoi nuhdella häntä.',
        33: 'Mutta hän kääntyi, katsoi opetuslapsiinsa ja nuhteli Pietaria sanoen: "Mene pois minun edestäni, saatana, sillä sinä et ajattele sitä, mikä on Jumalan, vaan sitä, mikä on ihmisten."',
        34: 'Hän kutsui luokseen kansan sekä opetuslapsensa ja sanoi heille: "Jos kuka tahansa tahtoo kulkea perässäni, hän kieltäköön itsensä ja ottakoon ristinsä ja seuratkoon minua.',
        35: 'Sillä se, joka tahtoo pelastaa elämänsä, kadottaa sen, mutta se, joka kadottaa elämänsä minun ja evankeliumin tähden, pelastaa sen.',
        36: 'Sillä mitä ihmistä hyödyttää, vaikka hän voittaisi omakseen koko maailman, mutta saisi sielulleen vahingon?',
        37: 'Sillä mitä ihminen voi antaa sielunsa lunnaiksi?',
        38: 'Sillä joka häpeää minua ja minun sanojani tässä avion rikkovassa ja syntisessä sukukunnassa, sitä myös Ihmisen Poika on häpeävä, kun hän tulee Isänsä kirkkaudessa pyhien enkelien kanssa."',
    },
    9: {
        1: 'Hän sanoi heille: "Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennen kuin näkevät Jumalan valtakunnan tulleena voimassaan."',
        2: 'Kuuden päivän kuluttua Jeesus otti mukaansa Pietarin, Jaakobin ja Johanneksen ja vei heidät erilleen muista korkealle vuorelle, yksinäisyyteen. Hänen muotonsa muuttui heidän edessään.',
        3: 'Hänen vaatteensa tulivat hohtaviksi, niin kovin valkoisiksi, ettei kukaan vaatteenvalkaisija maan päällä pysty valkaisemaan sellaiseksi.',
        4: 'Heille ilmestyi Elia Mooseksen kanssa, ja nämä keskustelivat Jeesuksen kanssa.',
        5: 'Pietari alkoi puhua ja sanoi Jeesukselle: "Rabbi, meidän on tässä hyvä olla. Tehkäämme kolme majaa, sinulle yksi, Moosekselle yksi ja Elialle yksi."',
        6: 'Sillä hän ei tiennyt, mitä sanoa, koska he olivat pelästyneet.',
        7: 'Tuli pilvi, joka peitti heidät varjoonsa, ja pilvestä kuului ääni: "Tämä on minun rakas Poikani, häntä kuulkaa."',
        8: 'Yhtäkkiä, kun he katsoivat ympärilleen, he eivät enää nähneet ketään muuta kuin Jeesuksen yksin heidän kanssaan.',
        9: 'Mutta heidän kulkiessaan alas vuorelta hän kielsi heitä kertomasta kenellekään, mitä olivat nähneet, ennen kuin vasta sitten, kun Ihmisen Poika oli noussut kuolleista.',
        10: 'He kiinnittivät huomionsa tähän sanaan ja tutkistelivat keskenään, mitä kuolleista nouseminen on.',
        11: 'He kysyivät häneltä sanoen: "Kirjanoppineethan sanovat, että Elian pitää tulla ensin?"',
        12: 'Hän vastasi ja sanoi heille: "Elia tosin tulee ensin ja asettaa kaikki kohdalleen. Mutta kuinka sitten on kirjoitettu Ihmisen Pojasta, että hän on paljon kärsivä ja tuleva halveksituksi?',
        13: 'Mutta minä sanon teille: Elia onkin tullut, ja he tekivät hänelle, mitä tahtoivat, kuten hänestä on kirjoitettu."',
        14: 'Kun he tulivat opetuslasten luo, he näkivät paljon kansaa heidän ympärillään ja kirjanoppineita väittelemässä heidän kanssaan.',
        15: 'Heti kun kaikki kansa näki hänet, he hämmästyivät ja riensivät hänen luokseen ja tervehtivät häntä.',
        16: 'Hän kysyi kirjanoppineilta: "Mitä te väittelette heidän kanssaan?"',
        17: 'Eräs mies kansanjoukosta vastasi hänelle ja sanoi: "Opettaja, minä toin luoksesi poikani, jossa on mykkä henki.',
        18: 'Missä vain se käy hänen kimppuunsa, se riuhtoo häntä, hänestä lähtee vaahto, hän kiristelee hampaitaan, ja hän kuihtuu. Sanoin opetuslapsillesi, että he ajaisivat sen ulos, mutta he eivät kyenneet."',
        19: 'Hän vastasi heille sanoen: "Voi, sinä epäuskoinen sukukunta, kuinka kauan minun täytyy olla teidän luonanne? Kuinka kauan kärsiä teitä? Tuokaa hänet luokseni."',
        20: 'He toivat hänet hänen luokseen. Heti kun hän näki Jeesuksen, kouristi henki häntä, ja hän kaatui maahan, kieriskeli siinä, ja hänestä lähti vaahto.',
        21: 'Jeesus kysyi hänen isältään: "Kuinka kauan tätä on ollut hänessä?" Hän sanoi: "Pienestä pitäen.',
        22: 'Monesti se on heittänyt hänet milloin tuleen, milloin veteen, tuhotakseen hänet. Mutta jos jotakin voit, auta meitä ja armahda meitä."',
        23: 'Jeesus sanoi hänelle: "Jospa voisit uskoa. Kaikki on mahdollista sille, joka uskoo."',
        24: 'Heti lapsen isä huusi ja sanoi kyynelin: "Minä uskon, auta minua epäuskossani."',
        25: 'Mutta kun Jeesus näki, että kansaa riensi sinne, hän nuhteli saastaista henkeä ja sanoi sille: "Sinä mykkä ja kuuro henki, minä käsken sinua: lähde ulos hänestä, äläkä enää mene häneen."',
        26: 'Se huusi, kouristi häntä kovasti ja lähti ulos. Hän kävi ikään kuin kuolleeksi, niin että monet sanoivat: "Hän kuoli."',
        27: 'Mutta Jeesus tarttui hänen käteensä ja nosti hänet ylös, ja hän nousi.',
        28: 'Kun Jeesus oli mennyt huoneeseen, hänen opetuslapsensa kysyivät häneltä erikseen: "Miksi me emme voineet ajaa sitä ulos?"',
        29: 'Hän sanoi heille: "Tätä lajia ei saa lähtemään ulos muulla kuin rukouksella ja paastolla."',
        30: 'He lähtivät sieltä ja kulkivat Galilean kautta, mutta hän ei tahtonut, että kukaan saisi tietää sitä.',
        31: 'Sillä hän opetti opetuslapsiaan ja sanoi heille: "Ihmisen Poika annetaan ihmisten käsiin, ja he tappavat hänet, ja kun hänet on tapettu, hän nousee kolmantena päivänä ylös."',
        32: 'Mutta he eivät käsittäneet sitä puhetta ja pelkäsivät kysyä häneltä.',
        33: 'He saapuivat Kapernaumiin. Kotiin tultuaan hän kysyi heiltä: "Mistä te tiellä keskustelitte?"',
        34: 'Mutta he olivat vaiti, sillä he olivat tiellä keskustelleet toistensa kanssa siitä, kuka oli suurin.',
        35: 'Istuuduttuaan hän kutsui ne kaksitoista ja sanoi heille: "Jos joku tahtoo olla ensimmäinen, hänen on oltava kaikista viimeinen ja kaikkien palvelija."',
        36: 'Hän otti lapsen, asetti sen heidän keskelleen ja otettuaan sen syliinsä sanoi heille:',
        37: '"Se, joka ottaa luokseen yhden tällaisen lapsen minun nimeeni, ottaa luokseen minut. Se, joka ottaa luokseen minut, ei ota luokseen minua, vaan hänet, joka on minut lähettänyt."',
        38: 'Johannes sanoi hänelle: "Opettaja, me näimme erään, joka ei seuraa meitä, sinun nimessäsi ajavan ulos riivaajia, ja kielsimme häntä, koska hän ei seurannut meitä."',
        39: 'Mutta Jeesus sanoi: "Älkää häntä kieltäkö, sillä ei kukaan, joka tekee voimateon minun nimeeni, voi heti sen jälkeen puhua minusta pahaa.',
        40: 'Sillä se, joka ei ole meitä vastaan, on meidän puolellamme.',
        41: 'Sillä se, joka antaa teille juodaksenne maljallisen vettä siinä nimessä, että olette Kristuksen omia, totisesti sanon teille: se ei jää palkkaansa vaille.',
        42: 'Joka viettelee yhden näistä pienistä, jotka uskovat, sen olisi parempi, että myllynkivi olisi pantu hänen kaulaansa ja hänet olisi heitetty mereen.',
        43: 'Jos sinun kätesi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että käsipuolena menet elämään sisälle kuin että molemmat kädet tallella menet helvettiin, sammumattomaan tuleen,',
        44: 'jossa heidän matonsa ei kuole eikä tuli sammu.',
        45: 'Jos jalkasi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että jalkapuolena menet elämään sisälle, kuin että sinut molemmat jalat tallella heitetään helvettiin,',
        46: 'jossa heidän matonsa ei kuole eikä tulensa sammu.',
        47: 'Jos sinun silmäsi viettelee sinua, heitä se pois. Parempi on sinulle, että silmäpuolena menet sisälle Jumalan valtakuntaan, kuin että sinut molemmat silmät tallella heitetään helvetin tuleen,',
        48: 'jossa heidän matonsa ei kuole eikä tuli sammu.',
        49: 'Sillä jokainen ihminen on tulella suolattava, ja jokainen uhri on suolalla suolattava.',
        50: 'Suola on hyvä, mutta jos suola käy suolattomaksi, millä sen suolaatte? Olkoon teillä suola itsessänne, ja pitäkää keskenänne rauha."',
    },
    10: {
        1: 'Hän nousi sieltä ja tuli Juudean alueelle kulkien Jordanin toista puolta. Jälleen kokoontui paljon kansaa hänen luokseen, ja tapansa mukaan hän taas opetti heitä.',
        2: 'Fariseuksia tuli hänen luokseen, ja kiusaten häntä he kysyivät häneltä, oliko miehen lupa hylätä vaimonsa.',
        3: 'Hän vastasi ja sanoi heille: "Mitä Mooses on teille säätänyt?"',
        4: 'He sanoivat: "Mooses salli kirjoittaa erokirjan ja hylätä vaimon."',
        5: 'Jeesus sanoi heille: "Teidän sydämenne kovuuden tähden hän kirjoitti teille tämän säädöksen.',
        6: "Mutta luomakunnan alusta Jumala 'on luonut heidät mieheksi ja naiseksi.",
        7: 'Sen tähden mies luopukoon isästään ja äidistään ja liittyköön vaimoonsa.',
        8: "Ne kaksi tulevat yhdeksi lihaksi.' Niin he eivät enää ole kaksi, vaan yksi liha.",
        9: 'Sitä, minkä siis Jumala on yhdistänyt, älköön ihminen erottako."',
        10: 'Sisällä opetuslapset taas kysyivät häneltä tätä asiaa.',
        11: 'Hän sanoi heille: "Se, joka hylkää vaimonsa ja nai toisen, tekee huorin häntä vastaan.',
        12: 'Jos vaimo hylkää miehensä ja menee naimisiin toisen kanssa, hän tekee huorin."',
        13: 'He toivat hänen luokseen lapsia, että hän koskisi heihin, mutta opetuslapset nuhtelivat tuojia.',
        14: 'Mutta kun Jeesus sen näki, hän närkästyi ja sanoi heille: "Sallikaa lasten tulla minun tyköni, älkääkä estäkö heitä, sillä sellaisten on Jumalan valtakunta.',
        15: 'Totisesti sanon teille: joka ei ota vastaan Jumalan valtakuntaa kuin lapsi, se ei tule sinne sisälle."',
        16: 'Hän otti heitä syliinsä, pani kätensä heidän päälleen ja siunasi heitä.',
        17: 'Hänen sieltä tielle mennessään juoksi muuan hänen luokseen, polvistui hänen eteensä ja kysyi häneltä: "Hyvä opettaja, mitä minun pitää tehdä, että iankaikkisen elämän perisin?"',
        18: 'Mutta Jeesus sanoi hänelle: "Miksi sanot minua hyväksi? Kukaan ei ole hyvä paitsi Jumala yksin.',
        19: 'Käskyt sinä tiedät: \'Älä tee huorin\', \'älä tapa\', \'älä varasta\', \'älä sano väärää todistusta\', \'älä anasta toiselta\', \'kunnioita isääsi ja äitiäsi.\'"',
        20: 'Mutta hän vastasi ja sanoi hänelle: "Opettaja, niitä kaikkia olen noudattanut nuoruudestani asti."',
        21: 'Jeesus katsoi häneen, rakasti häntä ja sanoi hänelle: "Yksi sinulta puuttuu: mene, myy kaikki, mitä sinulla on, ja anna köyhille, niin sinulla on oleva aarre taivaassa, ja tule ja seuraa minua ristiä kantaen."',
        22: 'Mutta hän synkistyi siitä puheesta ja meni pois murheellisena, sillä hänellä oli paljon omaisuutta.',
        23: 'Jeesus katsoi ympärilleen ja sanoi opetuslapsilleen: "Kuinka vaikea onkaan niiden, joilla on omaisuutta, tulla Jumalan valtakuntaan!"',
        24: 'Opetuslapset hämmästyivät hänen sanoistaan. Mutta Jeesus alkoi taas puhua ja sanoi heille: "Lapset, kuinka vaikea onkaan niiden, jotka luottavat omaisuuteensa, tulla Jumalan valtakuntaan!',
        25: 'Helpompi on kamelin mennä neulansilmästä kuin rikkaan tulla Jumalan valtakuntaan."',
        26: 'He hämmästyivät yhä enemmän ja sanoivat toisilleen: "Kuka sitten voi pelastua?"',
        27: 'Jeesus katsoi heihin ja sanoi: "Ihmisille se on mahdotonta, mutta ei Jumalalle, sillä Jumalalle on kaikki mahdollista."',
        28: 'Pietari rupesi puhumaan sanoen hänelle: "Katso, me olemme luopuneet kaikesta ja seuranneet sinua."',
        29: 'Jeesus sanoi: "Totisesti sanon teille: ei ole ketään, joka minun tähteni ja evankeliumin tähden on luopunut talosta, veljistä, sisarista, äidistä, isästä, lapsista tai pelloista,',
        30: 'ja joka ei saisi satakertaisesti: nyt tässä ajassa taloja, veljiä, sisaria, äitejä, lapsia ja peltoja, vainojen keskellä, ja tulevassa maailmassa iankaikkista elämää.',
        31: 'Mutta monet ensimmäiset tulevat viimeisiksi ja viimeiset ensimmäisiksi."',
        32: 'He olivat matkalla, menossa ylös Jerusalemiin, ja Jeesus kulki heidän edellään, ja heidät valtasi hämmästys, ja ne, jotka seurasivat, olivat peloissaan. Hän otti taas luokseen ne kaksitoista ja alkoi puhua heille, mitä hänelle oli tapahtuva:',
        33: '"Katso, menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylipappien ja kirjanoppineiden käsiin, ja he tuomitsevat hänet kuolemaan ja antavat hänet pakanoiden käsiin.',
        34: 'He pilkkaavat, sylkevät, ruoskivat häntä ja tappavat hänet, ja kolmen päivän perästä hän nousee ylös."',
        35: 'Jaakob ja Johannes, Sebedeuksen pojat, menivät hänen luokseen ja sanoivat hänelle: "Opettaja, tahtoisimme, että tekisit meille, mitä sinulta anomme."',
        36: 'Mutta hän sanoi heille: "Mitä tahdotte, että teille tekisin?"',
        37: 'Niin he sanoivat hänelle: "Anna meidän istua, toisen oikealla ja toisen vasemmalla puolellasi kirkkaudessasi."',
        38: 'Mutta Jeesus sanoi heille: "Te ette tiedä, mitä anotte. Voitteko juoda sen maljan, jonka minä juon, tai tulla kastetuiksi sillä kasteella, jolla minut kastetaan?"',
        39: 'He sanoivat hänelle: "Voimme." Niin Jeesus sanoi heille: "Sen maljan, jonka minä juon, tosin juotte, ja sillä kasteella, jolla minut kastetaan, kastetaan teidätkin,',
        40: 'mutta minun oikealla tai vasemmalla puolellani istuminen ei ole minun annettavissani, vaan se annetaan niille, joille se on valmistettu."',
        41: 'Kun ne kymmenen sen kuulivat, he alkoivat närkästyä Jaakobiin ja Johannekseen.',
        42: 'Mutta Jeesus kutsui heidät luokseen ja sanoi heille: "Tiedätte, että ne, joita kansojen ruhtinaiksi katsotaan, herroina niitä hallitsevat, ja että kansojen mahtavat käyttävät valtaansa niitä kohtaan.',
        43: 'Mutta näin ei tule olla teillä keskenänne, vaan se, joka teidän keskuudessanne tahtoo tulla suureksi, olkoon palvelijanne,',
        44: 'ja se, joka teidän keskuudessanne tahtoo olla ensimmäinen, olkoon kaikkien orja.',
        45: 'Sillä ei Ihmisen Poikakaan tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä."',
        46: 'He tulivat Jerikoon. Kun hän vaelsi Jerikosta opetuslastensa ja suuren väkijoukon seuraamana, istui sokea kerjäläinen, Bartimeus, Timeuksen poika, tien vieressä.',
        47: 'Kun hän kuuli, että se oli Jeesus Nasaretilainen, hän alkoi huutaa ja sanoa: "Jeesus, Daavidin poika, armahda minua."',
        48: 'Monet nuhtelivat häntä saadakseen hänet vaikenemaan. Mutta hän huusi vielä enemmän: "Daavidin poika, armahda minua."',
        49: 'Silloin Jeesus pysähtyi ja sanoi: "Kutsukaa hänet tänne." He kutsuivat sokean sanoen hänelle: "Ole turvallisella mielellä, nouse, hän kutsuu sinua."',
        50: 'Hän heitti viittansa päältään, nousi seisomaan ja tuli Jeesuksen luo.',
        51: 'Jeesus vastasi ja sanoi hänelle: "Mitä tahdot, että tekisin sinulle?" Sokea sanoi hänelle: "Rabbuuni, että saisin näköni jälleen."',
        52: 'Jeesus sanoi hänelle: "Mene, uskosi on sinut pelastanut." Heti hän sai näkönsä ja seurasi häntä tiellä.',
    },
    11: {
        1: 'Kun he sitten lähestyivät Jerusalemia tullen Beetfageen ja Betaniaan Öljymäen luona, hän lähetti kaksi opetuslastaan',
        2: 'ja sanoi heille: "Menkää edessänne olevaan kylään, niin te heti, kun sinne tulette, löydätte sidottuna varsan, jonka selässä ei kukaan ihminen ole vielä istunut. Päästäkää se ja tuokaa tänne.',
        3: 'Jos joku teille sanoo: \'Miksi te noin teette?\', sanokaa: \'Herra tarvitsee sitä ja lähettää sen heti tänne.\'"',
        4: 'Niin he menivät ja löysivät oven eteen ulos kujalle sidotun varsan ja päästivät sen.',
        5: 'Muutamat niistä, jotka siellä seisoivat, sanoivat heille: "Mitä teette, kun päästätte varsan?"',
        6: 'Niin he sanoivat heille, kuten Jeesus oli käskenyt, ja he päästivät heidät menemään.',
        7: 'He toivat varsan Jeesuksen luo ja heittivät vaatteensa sen päälle, ja hän istui sen selkään.',
        8: 'Monet levittivät vaatteensa tielle, ja toiset lehviä, joita katkoivat puista.',
        9: 'Ne, jotka kulkivat edellä, ja jotka seurasivat, huusivat: "Hoosianna, siunattu olkoon se, joka tulee Herran nimeen!',
        10: 'Siunattu olkoon isämme Daavidin valtakunta, joka tulee. Hoosianna korkeuksissa!"',
        11: 'Jeesus kulki Jerusalemiin ja meni pyhäkköön, ja katseltuaan kaikkea hän lähti niiden kahdentoista kanssa Betaniaan, sillä oli jo myöhä.',
        12: 'Kun he seuraavana päivänä lähtivät Betaniasta, hänen oli nälkä.',
        13: 'Kun hän näki kaukaa viikunapuun, jossa oli lehtiä, hän meni katsomaan, löytäisikö siitä jotakin, mutta tultuaan sen luo hän ei löytänyt muuta kuin lehtiä. Sillä ei ollut viikunoiden aika.',
        14: 'Hän puhui ja sanoi sille: "Älköön ikinä enää kukaan sinusta hedelmää syökö." Hänen opetuslapsensa kuulivat sen.',
        15: 'He tulivat Jerusalemiin. Hän meni pyhäkköön ja ryhtyi ajamaan ulos niitä, jotka myivät ja ostivat pyhäkössä, ja kaatoi kumoon rahanvaihtajien pöydät ja kyyhkysten myyjien istuimet,',
        16: 'eikä sallinut kenenkään kantaa mitään astiaa pyhäkön kautta.',
        17: 'Hän opetti ja sanoi heille: "Eikö ole kirjoitettu: \'Minun huoneeni on kutsuttava kaikkien kansojen rukoushuoneeksi\'? Mutta te olette tehneet siitä rosvojen luolan."',
        18: 'Ylipapit ja kirjanoppineet kuulivat sen ja miettivät, kuinka saisivat hänet surmatuksi, sillä he pelkäsivät häntä, koska kaikki kansa oli hämmästyksissään hänen opetuksestaan.',
        19: 'Kun ilta tuli, he menivät kaupungin ulkopuolelle.',
        20: 'Kun he sitten varhain aamulla kulkivat ohi, he näkivät viikunapuun kuivuneen juuria myöten.',
        21: 'Pietari muisti ja sanoi hänelle: "Rabbi, katso, viikunapuu, jonka kirosit, on kuivunut."',
        22: 'Jeesus vastasi ja sanoi heille: "Pitäkää usko Jumalaan.',
        23: "Totisesti sanon teille: jos joku sanoisi tälle vuorelle: 'Kohoa ja heittäydy mereen', eikä epäilisi sydämessään, vaan uskoisi sen tapahtuvan, minkä hän sanoo, niin se tapahtuisi hänelle.",
        24: 'Sen tähden sanon teille: kaikki, mitä te rukoilette ja anotte, uskokaa saaneenne, niin se on teillä oleva.',
        25: 'Kun seisotte ja rukoilette, niin antakaa anteeksi, jos jollakulla teistä on jotakin toistanne vastaan, että myös teidän Isänne, joka on taivaissa, antaisi teille anteeksi teidän rikkomisenne."',
        26: 'Mutta jos te ette anna anteeksi, niin ei Isännekään, joka on taivaissa, anna anteeksi teidän rikkomisianne.',
        27: 'He tulivat taas Jerusalemiin. Kun hän käveli pyhäkössä, tulivat ylipapit ja kirjanoppineet ja vanhimmat hänen luokseen',
        28: 'ja sanoivat hänelle: "Millä vallalla sinä näitä teet? Tai kuka on antanut sinulle vallan näitä tehdä?"',
        29: 'Mutta Jeesus vastasi heille: "Minäkin teen teille yhden kysymyksen. Vastatkaa minulle, niin sanon teille, millä vallalla näitä teen.',
        30: 'Oliko Johanneksen kaste taivaasta vai ihmisistä? Vastatkaa minulle."',
        31: 'He neuvottelivat keskenään sanoen: "Jos sanomme: \'Taivaasta\', hän sanoo: \'Miksi ette siis uskoneet häntä?\'.',
        32: 'Vai sanommeko: \'Ihmisistä\'?" – sitä he kansan tähden pelkäsivät sanoa, sillä kaikkien mielestä Johannes oli todella profeetta.',
        33: 'He vastasivat ja sanoivat Jeesukselle: "Emme tiedä." Silloin Jeesus vastasi ja sanoi heille: "Niinpä minäkään en sano teille, millä vallalla näitä teen."',
    },
    12: {
        1: 'Hän alkoi puhua heille vertauksilla: "Mies istutti viinitarhan, teki aidan sen ympärille, kaivoi viinikuurnan ja rakensi tornin. Hän vuokrasi sen viinitarhureille ja matkusti ulkomaille.',
        2: 'Kun aika tuli, hän lähetti palvelijan viinitarhurien luo perimään tarhureilta viinitarhan hedelmiä.',
        3: 'Mutta he ottivat hänet kiinni, ruoskivat ja lähettivät tyhjänä pois.',
        4: 'Vielä hän lähetti heidän luokseen toisen palvelijan. Mutta häntä he heittivät kivillä päähän ja häpäisivät.',
        5: 'Hän lähetti vielä toisen, ja hänet he tappoivat, ja samoin useita muita: toisia he löivät, toisia tappoivat.',
        6: "Vielä hänellä oli ainoa rakas poikansa. Hänet hän lähetti viimeiseksi heidän luokseen sanoen: 'Poikaani he kavahtavat.'",
        7: "Mutta viinitarhurit sanoivat toisilleen: 'Tämä on perillinen, tulkaa, tappakaamme hänet, niin perintö on meidän.'",
        8: 'He ottivat hänet kiinni, tappoivat ja heittivät hänet viinitarhan ulkopuolelle.',
        9: 'Mitä nyt viinitarhan isäntä tekee? Hän tulee ja tuhoaa viinitarhurit ja antaa viinitarhan muille.',
        10: "Ettekö ole lukeneet tätä kirjoitusta: 'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi.",
        11: 'Herralta tämä on tullut ja on ihmeellinen silmissämme\'?"',
        12: 'He etsivät häntä ottaakseen hänet kiinni, mutta he pelkäsivät kansaa, sillä he ymmärsivät, että hän oli puhunut tämän vertauksen heistä. He jättivät hänet ja menivät pois.',
        13: 'He lähettivät hänen luokseen muutamia fariseuksia ja herodeslaisia kietomaan häntä sanoilla.',
        14: 'Nämä tulivat ja sanoivat hänelle: "Opettaja, tiedämme, että sinä olet totuudellinen etkä välitä kenestäkään, sillä et katso henkilöön, vaan opetat Jumalan tietä totuudessa. Onko luvallista antaa keisarille veroa vai ei? Tuleeko meidän antaa vai ei?"',
        15: 'Mutta hän tiesi heidän tekopyhyytensä ja sanoi heille: "Miksi kiusaatte minua? Tuokaa denaari minun nähdäkseni."',
        16: 'He toivat. Hän sanoi heille: "Kenen kuva ja päällekirjoitus tämä on?" He vastasivat hänelle: "Keisarin."',
        17: 'Jeesus sanoi heille: "Antakaa keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on." He ihmettelivät häntä suuresti.',
        18: 'Hänen luokseen tuli saddukeuksia, jotka sanovat, ettei ylösnousemusta ole, ja he kysyivät häneltä sanoen:',
        19: '"Opettaja, Mooses on kirjoittanut meille: \'Jos joltakulta kuolee veli, joka jättää jälkeensä vaimon, mutta ei jätä lasta, niin ottakoon hän veljensä vaimon ja herättäköön veljelleen siemenen.\'',
        20: 'Oli seitsemän veljestä. Ensimmäinen otti vaimon, ja kun hän kuoli, häneltä ei jäänyt siementä.',
        21: 'Silloin toinen otti hänet, ja hänkin kuoli jättämättä siementä. Niin myös kolmas.',
        22: 'Samoin kävi kaikille seitsemälle: heiltä ei jäänyt siementä. Viimeiseksi kaikista vaimokin kuoli.',
        23: 'Ylösnousemuksessa siis, kun he nousevat ylös, kenelle heistä hän joutuu vaimoksi, sillä hän oli ollut kaikkien noiden seitsemän vaimona?"',
        24: 'Jeesus sanoi heille: "Eikö niin: te eksytte siitä syystä, ettette tunne Kirjoituksia ettekä Jumalan voimaa?',
        25: 'Sillä kun kuolleista noustaan, ei naida eikä mennä miehelle, vaan he ovat kuin enkelit taivaissa.',
        26: "Mutta mitä siihen tulee, että kuolleet herätetään, ettekö ole lukeneet Mooseksen kirjasta kertomuksessa orjantappurapensaasta, kuinka Jumala puhui hänelle sanoen: 'Minä olen Aabrahamin Jumala ja Iisakin Jumala ja Jaakobin Jumala'?",
        27: 'Ei hän ole kuolleiden Jumala, vaan elävien Jumala. Te siis suuresti eksytte."',
        28: 'Hänen luokseen tuli eräs kirjanoppinut, joka oli kuullut heidän keskustelunsa ja huomannut hänen hyvin vastanneen heille, ja kysyi häneltä: "Mikä on ensimmäinen kaikista käskyistä?"',
        29: 'Jeesus vastasi: "Ensimmäinen on tämä: \'Kuule, Israel: Herra, Jumalamme, Herra on yksi ainoa,',
        30: "ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi ja kaikesta voimastasi.'",
        31: 'Toinen on tämä: \'Rakasta lähimmäistäsi niin kuin itseäsi.\' Mitään muuta näitä suurempaa käskyä ei ole."',
        32: 'Kirjanoppinut sanoi hänelle: "Oikein sanoit, opettaja, totuuden mukaan, että Jumala on yksi, ja ettei ole ketään toista, paitsi hän.',
        33: 'Rakastaa häntä kaikesta sydämestään, kaikesta ymmärryksestään ja kaikesta voimastaan, ja rakastaa lähimmäistään niin kuin itseään on enemmän kuin kaikki polttouhrit ja muut uhrit."',
        34: 'Kun Jeesus näki, että hän vastasi ymmärtäväisesti, hän sanoi hänelle: "Sinä et ole kaukana Jumalan valtakunnasta." Kukaan ei enää uskaltanut esittää hänelle kysymyksiä.',
        35: 'Opettaessaan pyhäkössä Jeesus puhui edelleen ja sanoi: "Kuinka kirjanoppineet sanovat, että Kristus on Daavidin poika?',
        36: "Onhan Daavid itse sanonut Pyhässä Hengessä: 'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni, kunnes minä panen vihollisesi jalkojesi astinlaudaksi.'",
        37: 'Daavid itse sanoo häntä Herraksi, kuinka hän sitten on hänen poikansa?" Suuri kansanjoukko kuunteli häntä mielellään.',
        38: 'Opettaessaan hän sanoi: "Varokaa kirjanoppineita, jotka haluavat kulkea pitkissä viitoissa ja saada tervehdyksiä toreilla',
        39: 'ja etumaisia istuimia synagogissa ja ensimmäisiä sijoja pidoissa,',
        40: 'noita, jotka syövät leskien huoneet ja näön vuoksi pitävät pitkiä rukouksia. He saavat sitä kovemman tuomion."',
        41: 'Hän istui vastapäätä uhriarkkua ja katseli, kuinka kansa pani rahaa uhriarkkuun. Monet rikkaat panivat paljon.',
        42: 'Tuli köyhä leski ja pani kaksi ropoa, se on, jonkin kolikon.',
        43: 'Hän kutsui opetuslapsensa luokseen ja sanoi heille: "Totisesti sanon teille: tämä köyhä leski pani enemmän kuin kaikki muut, jotka panivat uhriarkkuun.',
        44: 'Sillä he kaikki panivat liiastaan. Mutta tämä pani puutteestaan kaiken, mitä hänellä oli, koko toimeentulonsa."',
    },
    13: {
        1: 'Kun hän meni ulos pyhäköstä, eräs hänen opetuslapsistaan sanoi hänelle: "Opettaja, katso, millaiset kivet ja millaiset rakennukset!"',
        2: 'Jeesus vastasi hänelle: "Näet nämä suuret rakennukset. Niistä ei ole jäävä kiveä kiven päälle maahan hajottamatta."',
        3: 'Kun hän istui Öljymäellä vastapäätä pyhäkköä, Pietari, Jaakob, Johannes ja Andreas kysyivät häneltä heidän ollessa keskenään:',
        4: '"Sano meille: milloin tämä tapahtuu, ja mikä on merkki siitä, että kaikki tämä alkaa lopullisesti toteutua?"',
        5: 'Jeesus vastasi ja ryhtyi puhumaan heille: "Katsokaa, ettei kukaan teitä eksytä.',
        6: "Monta tulee minun nimessäni sanoen: ' Minä olen ', ja he eksyttävät monta.",
        7: 'Kun kuulette sodista ja sanomia sodista, älkää pelästykö. Näin täytyy tapahtua, mutta se ei ole vielä loppu.',
        8: 'Sillä kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan, tulee maanjäristyksiä monin paikoin, ja on nälänhätää. Tämä on synnytystuskien alkua.',
        9: 'Mutta pitäkää te vaari itsestänne. Teitä vedetään oikeuteen, teitä ruoskitaan synagogissa, ja teitä viedään maaherrojen ja kuningasten eteen minun tähteni, todistukseksi heille.',
        10: 'Mutta ensiksi pitää evankeliumi saarnata kaikille kansoille.',
        11: 'Kun he vievät teitä ja jättävät tuomittaviksi, älkää edeltäpäin murehtiko, mitä puhuisitte, vaan mitä teille sillä hetkellä annetaan, se puhukaa. Sillä ette te ole puhumassa, vaan Pyhä Henki.',
        12: 'Veli antaa veljensä kuolemaan ja isä lapsensa, ja lapset nousevat vanhempiaan vastaan ja tappavat heitä.',
        13: 'Joudutte kaikkien vihattaviksi minun nimeni tähden. Mutta se, joka vahvana pysyy loppuun asti, pelastuu.',
        14: 'Mutta kun näette hävityksen kauhistuksen seisovan siinä, missä ei tulisi – se, joka tämän lukee, tarkatkoon – silloin ne, jotka Juudeassa ovat, paetkoot vuorille.',
        15: 'Se, joka on katolla, älköön astuko alas älköönkä menkö sisälle noutamaan huoneestaan mitään.',
        16: 'Se, joka on mennyt pellolle, älköön palatko takaisin hakemaan viittaansa.',
        17: 'Voi raskaana olevia ja imettäviä niinä päivinä!',
        18: 'Mutta rukoilkaa, ettei se tapahtuisi talvella.',
        19: 'Sillä niinä päivinä on oleva ahdistus, jollaista ei ole ollut Jumalan luoman luomakunnan alusta tähän asti, eikä milloinkaan tule.',
        20: 'Ellei Herra lyhentäisi niitä päiviä, mikään liha ei pelastuisi, mutta valittujen tähden, jotka hän on valinnut, hän on lyhentänyt ne päivät.',
        21: "Jos silloin joku sanoo teille: 'Katso, täällä on Kristus', tai: 'Katso, tuolla', älkää uskoko.",
        22: 'Sillä vääriä kristuksia ja vääriä profeettoja nousee, ja he tekevät tunnustekoja ja ihmeitä eksyttääkseen, jos mahdollista, valitutkin.',
        23: 'Mutta olkaa te varuillanne. Katso, olen edeltä sanonut teille kaiken.',
        24: 'Mutta niinä päivinä, sen ahdistuksen jälkeen, aurinko pimenee, eikä kuu anna valoaan,',
        25: 'ja tähtiä putoilee taivaalta, ja voimat, jotka ovat taivaissa, järkkyvät.',
        26: 'He näkevät Ihmisen Pojan tulevan pilvissä suurella voimalla ja kirkkaudella.',
        27: 'Hän lähettää enkelinsä ja kokoaa valittunsa neljältä ilmansuunnalta, maan äärestä aina taivaan ääreen.',
        28: 'Mutta oppikaa viikunapuusta vertaus: Kun sen oksa on jo tuore ja lehdet puhkeavat, tiedätte, että kesä on lähellä.',
        29: 'Samoin myös, kun näette tämän tapahtuvan, tietäkää, että se on lähellä, oven edessä.',
        30: 'Totisesti sanon teille: tämä sukukunta ei katoa, ennen kuin kaikki nämä tapahtuvat.',
        31: 'Taivas ja maa katoavat, mutta minun sanani eivät katoa.',
        32: 'Mutta siitä päivästä tai hetkestä ei tiedä kukaan, eivät enkelit taivaassa, eikä myöskään Poika, paitsi Isä.',
        33: 'Olkaa varuillanne, valvokaa ja rukoilkaa, sillä ette tiedä, milloin se aika on.',
        34: 'On kuin matkoille lähteneen miehen: kun hän jätti talonsa ja valtuutti palvelijansa antaen kullekin oman tehtävänsä, hän käski myös ovenvartijan valvoa.',
        35: 'Valvokaa siis, sillä ette tiedä, milloin talon isäntä tulee, myöhään illalla, keskellä yötä, kukonlaulun aikaan vai varhain aamulla,',
        36: 'ettei hän tullessaan äkkiarvaamatta tapaisi teitä nukkumasta.',
        37: 'Mutta minkä teille sanon, sen sanon kaikille: valvokaa."',
    },
    14: {
        1: 'Sitten oli kahden päivän perästä pääsiäinen ja happamattoman leivän juhla, ja ylipapit ja kirjanoppineet etsivät, kuinka saisivat hänet otetuksi kavaluudella kiinni ja tapetuksi.',
        2: 'Sillä he sanoivat: "Ei juhlan aikana, ettei syntyisi meteliä kansassa."',
        3: 'Kun hän oli Betaniassa, spitaalisen Simonin asunnossa, tuli hänen aterialla ollessaan nainen, mukanaan alabasteripullo täynnä oikeaa, kallista nardusvoidetta. Hän rikkoi alabasteripullon ja vuodatti voiteen hänen päähänsä.',
        4: 'Oli muutamia, jotka närkästyivät ja sanoivat keskenään: "Miksi tämä voiteen haaskaus?',
        5: 'Olisihan tämän voinut myydä enempään kuin kolmeensataan denaariin ja antaa ne köyhille." He nuhtelivat häntä.',
        6: 'Mutta Jeesus sanoi: "Antakaa hänen olla. Miksi pahoitatte hänen mielensä? Hän teki hyvän työn minulle.',
        7: 'Köyhät teillä on aina keskuudessanne, ja milloin tahdotte, voitte tehdä hyvää heille, mutta minua teillä ei ole aina.',
        8: 'Hän teki, minkä voi. Edeltäkäsin hän voiteli ruumiini hautaamista varten.',
        9: 'Totisesti sanon teille: missä ikinä kaikessa maailmassa evankeliumia saarnataan, siellä sekin, minkä tämä teki, julistetaan hänen muistokseen."',
        10: 'Juudas Iskariot, yksi niistä kahdestatoista, meni ylipappien luo kavaltaakseen hänet heille.',
        11: 'Kun nämä sen kuulivat, he ihastuivat ja lupasivat antaa hänelle rahaa. Hän mietti, kuinka kavaltaisi hänet sopivassa tilaisuudessa.',
        12: 'Ensimmäisenä happamattoman leivän päivänä, kun pääsiäislammas teurastettiin, hänen opetuslapsensa sanoivat hänelle: "Mihin tahdot, että menemme valmistamaan pääsiäislampaan sinun syödäksesi?"',
        13: 'Hän lähetti kaksi opetuslastaan ja sanoi heille: "Menkää kaupunkiin, niin teitä vastaan tulee mies kantaen vesiastiaa, seuratkaa häntä.',
        14: "Mihin hän menee, sanokaa talon isännälle: 'Opettaja sanoo: Missä on vierashuoneeni syödäkseni siinä pääsiäislampaan opetuslasteni kanssa?'",
        15: 'Hän näyttää teille suuren huoneen yläkerrassa, valmiiksi laitetun, valmistakaa meille sinne."',
        16: 'Opetuslapset lähtivät ja tulivat kaupunkiin ja havaitsivat niin olevan, kuin Jeesus oli heille sanonut, ja valmistivat pääsiäislampaan.',
        17: 'Kun ehtoo tuli, hän saapui sinne niiden kahdentoista kanssa.',
        18: 'Kun he olivat aterialla ja söivät, Jeesus sanoi: "Totisesti sanon teille: yksi teistä kavaltaa minut, eräs, joka syö kanssani."',
        19: 'He tulivat murheellisiksi ja rupesivat toinen toisensa perästä sanomaan hänelle: "Enhän minä se ole?" Ja toinen: "Enhän minä se ole?"',
        20: 'Mutta hän vastasi ja sanoi heille: "Yksi teistä kahdestatoista, se, joka kastaa [leipää] vatiin minun kanssani.',
        21: 'Niin, Ihmisen Poika tosin menee pois, kuten hänestä on kirjoitettu, mutta voi sitä ihmistä, joka Ihmisen Pojan kavaltaa! Parempi olisi sille ihmiselle, ettei hän olisi syntynyt."',
        22: 'Heidän syödessään Jeesus otti leivän, siunasi, mursi, antoi heille ja sanoi: "Ottakaa, tämä on minun ruumiini."',
        23: 'Hän otti maljan, kiitti ja antoi heille, ja he kaikki joivat siitä.',
        24: 'Hän sanoi heille: "Tämä on minun vereni, liiton veri, joka vuodatetaan monen edestä.',
        25: 'Totisesti sanon teille: en juo enää viinipuun antia, ennen kuin sinä päivänä, jona juon sitä uutena Jumalan valtakunnassa."',
        26: 'Lausuttuaan kiitosvirren he lähtivät Öljymäelle.',
        27: 'Jeesus sanoi heille: "Kaikki te loukkaannutte minuun tänä yönä, sillä kirjoitettu on: \'Lyön paimenta, ja lampaat hajotetaan.\'',
        28: 'Mutta ylösnoustuani menen edellänne Galileaan."',
        29: 'Pietari sanoi hänelle: "Vaikka kaikki loukkaantuisivat, en kuitenkaan minä."',
        30: 'Jeesus sanoi hänelle: "Totisesti sanon sinulle: tänään, tänä yönä, ennen kuin kukko kahdesti laulaa, sinä kolmesti minut kiellät."',
        31: 'Mutta hän vakuutti vielä lujemmin: "Vaikka minun pitäisi kuolla sinun kanssasi, en sittenkään kiellä sinua." Ja samoin sanoivat kaikki muutkin.',
        32: 'He tulivat maatilalle, jonka nimi on Getsemane, ja hän sanoi opetuslapsilleen: "Istukaa tässä sillä aikaa, kun rukoilen."',
        33: 'Hän otti mukaansa Pietarin, Jaakobin ja Johanneksen, ja hän alkoi kauhistua ja tulla tuskaan.',
        34: 'Hän sanoi heille: "Minun sieluni on syvästi murheellinen, kuolemaan asti, olkaa tässä ja valvokaa."',
        35: 'Hän meni vähän edemmäksi, lankesi maahan ja rukoili, että, jos mahdollista, se hetki menisi häneltä ohi,',
        36: 'ja sanoi: "Abba, Isä, kaikki on mahdollista sinulle, ota pois minulta tämä malja. Mutta ei mitä minä tahdon, vaan mitä sinä!"',
        37: 'Hän tuli ja tapasi heidät nukkumasta ja sanoi Pietarille: "Simon, nukutko? Etkö jaksanut yhtä hetkeä valvoa?',
        38: 'Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen. Henki tosin on altis, mutta liha on heikko."',
        39: 'Hän meni taas pois ja rukoili sanoen samat sanat.',
        40: 'Tullessaan hän tapasi taas heidät nukkumasta, sillä heidän silmänsä olivat käyneet kovin raskaiksi, eivätkä he tienneet, mitä vastaisivat hänelle.',
        41: 'Hän tuli kolmannen kerran ja sanoi heille: "Nukutte vielä ja lepäätte! Jo riittää! Hetki on tullut, katso, Ihmisen Poika annetaan syntisten käsiin.',
        42: 'Nouskaa, lähtekäämme, katso, se, joka kavaltaa minut, on lähellä."',
        43: 'Heti hänen vielä puhuessaan Juudas, yksi niistä kahdestatoista, saapui, ja hänen mukanaan suuri joukko ylipappien, kirjanoppineiden ja vanhinten luota, miekat ja seipäät käsissä.',
        44: 'Mutta se, joka hänet kavalsi, antoi heille merkin sanoen: "Se, jota tervehdin suudelmalla, hän se on. Ottakaa hänet kiinni ja viekää tarkasti vartioituna pois."',
        45: 'Tultuaan hän heti astui hänen luokseen ja sanoi: "Rabbi!" ja tervehti häntä suudelmalla.',
        46: 'He kävivät häneen käsiksi ja ottivat hänet kiinni.',
        47: 'Mutta eräs niistä, jotka seisoivat lähellä, veti miekkansa, iski ylipapin palvelijaa ja sivalsi häneltä pois korvan.',
        48: 'Niin Jeesus puhui heille ja sanoi: "Niin kuin ryöväriä vastaan te olette lähteneet minua miekoilla ja seipäillä vangitsemaan.',
        49: 'Joka päivä olen ollut luonanne opettaen pyhäkössä, ettekä ole ottaneet minua kiinni. Mutta tämä tapahtuu, että Kirjoitukset kävisivät toteen."',
        50: 'He kaikki jättivät hänet ja pakenivat.',
        51: 'Häntä seurasi eräs nuorukainen, jolla oli ympärillään liinavaate paljaalle iholle heitettynä, ja nuoret miehet ottivat hänet kiinni.',
        52: 'Mutta hän jätti liinavaatteen ja pakeni alasti.',
        53: 'He veivät Jeesuksen ylipapin eteen, jonne kaikki ylipapit, vanhimmat ja kirjanoppineet kokoontuivat.',
        54: 'Pietari seurasi häntä taaempana ylipapin palatsin esipihaan asti ja istuutui palvelijoiden joukkoon ja lämmitteli tulella.',
        55: 'Mutta ylipapit ja koko neuvosto etsivät todistusta Jeesusta vastaan tappaakseen hänet, mutta eivät löytäneet.',
        56: 'Monet kyllä todistivat väärin häntä vastaan, mutta todistukset eivät olleet yhtäpitäviä.',
        57: 'Muutamat nousivat ja todistivat väärin häntä vastaan sanoen:',
        58: '"Me olemme kuulleet hänen sanovan: \'Minä hajotan maahan tämän käsillä tehdyn temppelin ja rakennan kolmessa päivässä toisen, joka ei ole käsillä tehty.\'"',
        59: 'Mutta näinkään heidän todistuksensa eivät olleet yhtäpitäviä.',
        60: 'Silloin ylipappi nousi, astui esiin ja kysyi Jeesukselta sanoen: "Etkö vastaa mitään? Mitä nämä todistavat sinua vastaan?"',
        61: 'Mutta hän oli vaiti eikä vastannut mitään. Taas ylipappi kysyi häneltä ja sanoi hänelle: "Oletko sinä Kristus, sen Ylistetyn Poika?"',
        62: 'Jeesus sanoi: " Minä olen, ja te saatte nähdä Ihmisen Pojan istuvan Voiman oikealla puolella ja tulevan taivaan pilvissä."',
        63: 'Ylipappi repäisi vaatteensa ja sanoi: "Mitä enää todistajia tarvitsemme?',
        64: 'Kuulitte hänen pilkkaamisensa. Mitä arvelette?" Niin he kaikki tuomitsivat hänet syylliseksi kuolemaan.',
        65: 'Muutamat rupesivat sylkemään hänen päälleen, peittivät hänen kasvonsa, löivät häntä nyrkillä ja sanoivat hänelle: "Profetoi!" Palvelijatkin löivät häntä poskelle.',
        66: 'Kun nyt Pietari oli alhaalla pihassa, sinne tuli eräs ylipapin palvelustytöistä.',
        67: 'Nähdessään Pietarin lämmittelevän hän katsoi häneen ja sanoi: "Sinäkin olit Jeesus Nasaretilaisen kanssa."',
        68: 'Mutta hän kielsi sanoen: "En tiedä enkä käsitä, mitä sanot." Hän meni ulos pihalle, ja kukko lauloi.',
        69: 'Nähdessään hänet siellä palvelustyttö rupesi taas sanomaan lähellä seisoville: "Tämä on yksi niistä."',
        70: 'Mutta hän kielsi uudestaan. Vähän sen jälkeen lähellä seisoneet taas sanoivat Pietarille: "Totisesti, olet yksi niistä, sillä olethan galilealainenkin. Puheesikin on sellaista."',
        71: 'Mutta hän alkoi kirota itseään ja vannoa: "En tunne sitä miestä, josta te puhutte."',
        72: 'Samassa kukko lauloi toisen kerran. Pietari muisti Jeesuksen sanat, jotka hän oli sanonut hänelle: "Ennen kuin kukko kahdesti laulaa, [sinä] kiellät minut kolmesti." Ja hän purskahti itkuun.',
    },
    15: {
        1: 'Heti varhain aamulla ylipapit, vanhimmat, kirjanoppineet ja koko Neuvosto pidettyään neuvottelun sitoivat Jeesuksen, veivät hänet pois ja luovuttivat Pilatukselle.',
        2: 'Pilatus kysyi häneltä: "Oletko sinä juutalaisten kuningas?" Hän vastasi ja sanoi hänelle: "Sinä sen sanot."',
        3: 'Ylipapit tekivät monta syytöstä häntä vastaan, mutta hän ei vastannut mitään.',
        4: 'Pilatus kysyi taas häneltä sanoen: "Etkö vastaa mitään? Katso, kuinka paljon syytöksiä he tekevät sinua vastaan."',
        5: 'Mutta Jeesus ei enää vastannut mitään, niin että se hämmästytti Pilatusta.',
        6: 'Mutta juhlan aikana hänellä oli tapana vapauttaa heille yksi vanki, se, jota he anoivat.',
        7: 'Siellä oli eräs mies, jota sanottiin Barabbaaksi, vangittu muiden kapinoitsijoiden kanssa, jotka kapinassa olivat tehneet murhan.',
        8: 'Kansa meni sinne ylös ja rupesi pyytämään, että hän tekisi heille, kuten hänellä oli tapana.',
        9: 'Pilatus vastasi heille sanoen: "Tahdotteko, että päästän teille juutalaisten kuninkaan?"',
        10: 'Sillä hän tiesi, että ylipapit olivat kateudesta luovuttaneet hänet hänelle.',
        11: 'Mutta ylipapit kiihottivat kansaa anomaan, että hän ennemmin vapauttaisi heille Barabbaan.',
        12: 'Mutta Pilatus vastasi ja puhui taas heille ja sanoi: "Mitä minun sitten on tehtävä sille, jota te sanotte juutalaisten kuninkaaksi?"',
        13: 'Niin he taas huusivat: "Ristiinnaulitse hänet!"',
        14: 'Mutta Pilatus sanoi heille: "Mitä pahaa hän on tehnyt?" Mutta he huusivat vielä kovemmin: "Ristiinnaulitse hänet!"',
        15: 'Kun Pilatus tahtoi tehdä kansalle mieliksi, hän vapautti heille Barabbaan, mutta Jeesuksen hän ruoskitti ja luovutti ristiinnaulittavaksi.',
        16: 'Sotamiehet veivät hänet sisälle esipihaan, se on maaherran virka-asuntoon, ja kutsuivat sinne koko kohortin.',
        17: 'He pukivat hänen päälleen purppuravaatteen, väänsivät orjantappuroista kruunun ja panivat sen hänen päähänsä',
        18: 'ja rupesivat tervehtimään häntä: "Terve, juutalaisten kuningas!"',
        19: 'He löivät häntä päähän ruokokepillä, sylkivät hänen päälleen ja laskeutuen polvilleen kumarsivat häntä.',
        20: 'Kun he olivat häntä pilkanneet, he riisuivat häneltä purppuraviitan, pukivat hänet hänen omiin vaatteisiinsa ja veivät hänet pois ristiinnaulitakseen hänet.',
        21: 'He pakottivat erään ohikulkevan miehen, Simonin, kyreneläisen, joka tuli pellolta, Aleksanterin ja Rufuksen isän, kantamaan hänen ristiään.',
        22: 'He veivät hänet paikalle, jonka nimi on Golgata, se on käännettynä: pääkallonpaikka.',
        23: 'He tarjosivat hänelle mirhalla sekoitettua viiniä, mutta hän ei ottanut sitä.',
        24: 'He ristiinnaulitsivat hänet ja jakoivat keskenään hänen vaatteensa heittäen niistä arpaa, mitä kukin oli saava.',
        25: 'Oli kolmas tunti, kun he hänet ristiinnaulitsivat.',
        26: 'Päällekirjoitukseksi oli merkitty hänen syynsä: "Juutalaisten kuningas."',
        27: 'He ristiinnaulitsivat hänen kanssaan kaksi ryöväriä, toisen hänen oikealle ja toisen hänen vasemmalle puolelleen.',
        28: 'Niin kävi toteen Raamattu, joka sanoo: "Hänet luettiin pahantekijöiden joukkoon."',
        29: 'Ohikulkijat herjasivat häntä ja nyökyttivät päätään ja sanoivat: "Voi sinua, joka hajotat maahan temppelin ja kolmessa päivässä sen rakennat!',
        30: 'Auta itseäsi ja astu alas ristiltä."',
        31: 'Samoin ylipapitkin sekä kirjanoppineet pilkkasivat häntä keskenään ja sanoivat: "Muita hän on auttanut, itseään ei voi auttaa.',
        32: 'Astukoon hän, Kristus, Israelin kuningas, nyt alas ristiltä, että näkisimme ja uskoisimme." Myös ne, jotka olivat ristiinnaulitut hänen kanssaan, herjasivat häntä.',
        33: 'Kuudennella tunnilla tuli pimeys yli koko maan, ja sitä kesti aina yhdeksänteen tuntiin.',
        34: 'Yhdeksännellä tunnilla Jeesus huusi suurella äänellä: "Eeli, Eeli, lama sabaktani?" Se on käännettynä: Jumalani, Jumalani, miksi minut hylkäsit?',
        35: 'Sen kuullessaan sanoivat muutamat niistä, jotka siinä seisoivat: "Katso, hän huutaa Eliaa."',
        36: 'Eräs mies juoksi ja täytti sienen hapanviinillä, pani sen ruokokepin päähän ja antoi hänelle juoda sanoen: "Annahan olla, katsokaamme, tuleeko Elia ottamaan hänet alas."',
        37: 'Mutta Jeesus huusi suurella äänellä ja antoi henkensä.',
        38: 'Temppelin esirippu repesi kahtia ylhäältä alas asti.',
        39: 'Mutta kun sadanpäällikkö, joka seisoi häntä vastapäätä, näki hänen tällä tavalla antavan henkensä, hän sanoi: "Totisesti tämä ihminen oli Jumalan Poika."',
        40: 'Siellä oli myös naisia taaempaa katselemassa. Näiden joukossa olivat Maria Magdaleena ja Maria, Jaakob nuoremman ja Jooseen äiti, sekä Salome,',
        41: 'jotka hänen ollessaan Galileassa olivat seuranneet ja palvelleet häntä, sekä monia muita, jotka olivat tulleet hänen kanssaan ylös Jerusalemiin.',
        42: 'Kun ilta oli jo tullut, ja koska oli valmistuspäivä, se on sapatin aattopäivä,',
        43: 'tuli Joosef, arimatialainen, arvossapidetty Neuvoston jäsen, joka hänkin odotti Jumalan valtakuntaa, rohkaisi mielensä ja meni sisälle Pilatuksen luo ja pyysi Jeesuksen ruumista.',
        44: 'Pilatus ihmetteli, oliko hän jo kuollut, ja kutsuttuaan luokseen sadanpäällikön kysyi tältä, oliko hän jo kauan sitten kuollut.',
        45: 'Saatuaan sadanpäälliköltä tiedon siitä hän lahjoitti ruumiin Joosefille.',
        46: 'Tämä osti liinavaatteen, otti hänet alas, kääri hänet liinavaatteeseen, pani hautaan, joka oli hakattu kallioon, ja vieritti kiven haudan ovelle.',
        47: 'Maria Magdaleena ja Maria, Jooseen äiti, katselivat, mihin hänet pantiin.',
    },
    16: {
        1: 'Sapatin mentyä ohi ostivat Maria Magdaleena ja Maria, Jaakobin äiti, sekä Salome hyvänhajuisia yrttejä mennäkseen voitelemaan hänet.',
        2: 'Ani varhain viikon ensimmäisenä päivänä he tulivat haudalle, auringon noustessa',
        3: 'ja sanoivat toisilleen: "Kuka vierittää meille kiven haudan ovelta?"',
        4: 'Kohotettuaan katseensa he näkivät kiven poisvieritetyksi, se oli näet hyvin suuri.',
        5: 'Mentyään sisälle hautaan he näkivät nuorukaisen istuvan oikealla puolella puettuna pitkään, valkoiseen vaatteeseen, ja pelästyivät suuresti.',
        6: 'Mutta hän sanoi heille: "Älkää pelästykö, te etsitte Jeesusta, Nasaretilaista, joka oli ristiinnaulittu. Hänet on herätetty kuolleista, hän ei ole täällä. Katso, tässä on paikka, johon he hänet panivat.',
        7: 'Mutta menkää ja sanokaa hänen opetuslapsilleen ja Pietarille: \'Hän menee teidän edellänne Galileaan, siellä näette hänet, kuten hän teille sanoi.\'"',
        8: 'He tulivat ulos nopeasti ja pakenivat haudalta, sillä he vapisivat järkyttyneinä eivätkä sanoneet kenellekään mitään, sillä he pelkäsivät.',
        9: 'Mutta ylösnoustuaan hän varhain aamulla viikon ensimmäisenä päivänä ilmestyi ensiksi Maria Magdaleenalle, josta hän oli ajanut ulos seitsemän riivaajaa.',
        10: 'Tämä meni ja vei sanan niille, jotka olivat olleet Jeesuksen kanssa ja jotka nyt murehtivat ja itkivät.',
        11: 'Kun he kuulivat, että hän eli ja että Maria oli nähnyt hänet, he eivät uskoneet.',
        12: 'Mutta sen jälkeen hän toisenmuotoisena ilmestyi kahdelle heistä heidän kävellessään maaseudulle.',
        13: 'Hekin menivät ja veivät sanan toisille, jotka eivät kuitenkaan uskoneet heitä.',
        14: 'Vihdoin hän ilmestyi myös niille yhdelletoista heidän ollessaan aterialla. Hän nuhteli heidän epäuskoaan ja heidän sydämensä kovuutta, kun he eivät olleet uskoneet niitä, jotka olivat nähneet hänet kuolleista herätettynä.',
        15: 'Hän sanoi heille: "Menkää kaikkeen maailmaan ja saarnatkaa evankeliumi kaikille luoduille.',
        16: 'Joka uskoo ja tulee kastetuksi, se pelastuu, mutta se, joka ei usko, tuomitaan kadotukseen.',
        17: 'Nämä merkit seuraavat niitä, jotka uskovat: minun nimessäni he ajavat ulos riivaajia, puhuvat uusilla kielillä,',
        18: 'nostavat käsin käärmeitä, ja jos he juovat jotakin kuolettavaa, se ei vahingoita heitä. He panevat kätensä sairaiden päälle, ja nämä paranevat."',
        19: 'Kun nyt Herra Jeesus oli puhunut heille, otettiin hänet ylös taivaaseen, ja hän istuutui Jumalan oikealle puolelle.',
        20: 'Mutta he lähtivät ja saarnasivat kaikkialla, ja Herra vaikutti heidän kanssaan ja vahvisti sanan sitä seuraavien merkkien kautta. Aamen.',
    },
}
